(window.__BOOKS=window.__BOOKS||{})["e_bacchae"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"dionis\">Дионис</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Хор вакханок, лидийских женщин</span>"],["person","<span class=\"pn\">Тиресий, слепой старик, прорицатель</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Кадм, бывший царь фиванский</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Пенфей, юноша, внук <span class=\"ch\" data-ch=\"kadm\">Кадма</span>, новый царь фиванский</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Слуга</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Вестник-пастух</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Вестник-слуга</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Агава, дочь <span class=\"ch\" data-ch=\"kadm\">Кадма</span>, мать <span class=\"ch\" data-ch=\"penfey\">Пенфея</span></span> <span class=\"act-no\">(I)</span>"],["place","Действие происходит в Кадмее, фиванской крепости, к северу от Фив, перед дворцом Кадма. Фасад дворца в дорийском стиле, с колоннами и триглифом. Средняя дверь играет роль главных ворот, ведущих внутрь помещения. У правой периакты (кулисы) куча деревянных обломков, огороженных и обвитых зеленью винограда. При начале пьесы выходит на сцену слева Дионис в виде поклонника Вакха: сверх длинного, до самых пят, пестрого хитона у него шафранного цвета перекидка, которую стягивает широкий пестрый пояс; по накидке свешивается с плеч небрида — ланья шкура; с головы из-под мягкой митры и плюшевого венка роскошными локонами падают на плечи нежные, светло-золотистые волосы, закрывающие уши и часть щек. ⟨Он имеет вид⟩ изнеженного красавца с женоподобным лицом; щеки белые, с густым румянцем (глаза с поволокой); в правой руке у него тирс, палка в рост человека, обвитая плющом."],["act","Пролог","a1",""],["scene","Явление первое","s1",1,1],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Сын Зевса, Дионис, я — у фиванцев.",0,1,0,0],["v","Здесь некогда Семела, <span class=\"ch\" data-ch=\"kadm\">Кадма</span> дочь,",0,1,0,0],["v","Меня на свет безвременно явила,",0,1,0,0],["v","Огнем Зевесовой грозы поражена.",0,2,0,0],["v","Из бога став по виду человеком,",0,3,0,0],["v","Я подхожу к струям родимых рек.",0,4,0,0],["sd","(Видит обломки, увитые виноградом.)"],["v","Вот матери моей сожженной память",0,5,0,0],["v","У самого дворца обломки дома",0,6,0,0],["v","Еще курятся, — в них еще живет",0,7,0,0],["v","Огонь небесный, Геры горделивой",0,8,0,0],["v","На мать мою неугасимый гнев…",0,9,0,0],["v","Как хорошо, что сделал неприступным",0,10,0,1],["v","<span class=\"ch\" data-ch=\"kadm\">Кадм</span> дочери святилище; его",0,10,0,0],["v","Со всех сторон я скрыл и винограда",0,11,0,0],["v","Кистями нежной зелени обвил.",0,11,0,0],["v","Богатой Лидии равнины я покинул",0,12,1,0],["v","И Фригию, и Персии поля,",0,13,0,0],["v","Сожженные полдневными лучами,",0,13,0,0],["v","И стены Бактрии, и у мидян",0,14,0,0],["v","Изведав холод зимний, я арабов",0,15,0,0],["v","Счастливых посетил и обошел",0,15,0,0],["v","Всю Азию, что по прибрежью моря",0,16,0,0],["v","Соленого простерлась: в городах",0,16,0,0],["v","Красиво высятся стенные башни,",0,17,0,0],["v","И вместе там грек с варваром живет.",0,18,0,0],["v","Я в Азии ввел праздники и пляски",0,18,0,0],["v","И от людей, как бог, везде почтен.",0,19,0,0],["v","Здесь почву Греции впервые попираю.",0,20,0,1],["v","Из городов Эллады раньше всех",0,21,1,0],["v","Вас, Фивы, я наполню ликованьем,<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,22,0,0],["v","Небриды на плечи накину и, взамен<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,23,0,0],["v","Копья, вручу вам тирс, плющом увитый:",0,24,0,0],["v","Здесь сестры матери — кто мог бы ожидать?<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,25,0,0],["v","Во мне Зевеса сына не признали,",0,26,0,0],["v","И утверждали, будто, согрешив",0,27,0,0],["v","Со смертным, мать Зевесу приписала",0,28,0,0],["v","Свой женский грех, что ловко сочинил",0,30,0,1],["v","Ту басню <span class=\"ch\" data-ch=\"kadm\">Кадм</span>, и будто Зевс Семелу",0,30,0,0],["v","Убил за дерзко выдуманный брак.",0,31,0,0],["v","Я, бешенством объяв их, из домов",0,32,0,0],["v","Бежать заставил, — потеряв рассудок",0,33,0,0],["v","Они теперь ушли на Киферон",0,33,0,0],["v","В вакхических одеждах, с жаждой оргий",0,34,0,0],["v","В груди, и сколько в Фивах есть",0,35,0,0],["v","Народу женского, всех с ними вместе",0,36,0,0],["v","Заставил я покинуть очаги.",0,36,0,0],["v","И под шатрами елей, как попало,",0,37,0,0],["v","Бездомные на голых спят скалах.",0,38,0,0],["v","Да, город, ты почувствуешь теперь,",0,39,1,0],["v","Что до сих пор чуждался оргий <span class=\"ch\" data-ch=\"dionis\">Вакха</span>.",0,40,0,1],["v","Семелы матери я память защитить",0,40,0,0],["v","Являюсь мощным богом, сыном Зевса.",0,41,0,0],["v","Почет и власть царя здесь отдал <span class=\"ch\" data-ch=\"kadm\">Кадм</span>",0,42,0,0],["v","Пенфею, сыну дочери <span class=\"ch\" data-ch=\"agava\">Агавы</span>.",0,43,0,0],["v","Он богоборец и ни разу мне",0,44,0,0],["v","Не сделал возлиянья и в молитвах.",0,45,0,0],["v","Упоминать не хочет. Пусть же царь",0,46,0,0],["v","И прочие фиванцы убедятся,",0,47,0,0],["v","Что точно бог я. Здесь как научу",0,48,0,0],["v","Себе служить, пойду в другие земли.",0,49,0,0],["v","А если с войском двинутся фиванцы,",0,50,0,1],["v","Чтоб женщин с Киферона возвратить,",0,51,0,0],["v","Затеют с ними бой мои менады.",0,52,1,0],["v","Так вот зачем, обличье изменив,",0,53,0,0],["v","Из бога стал я с виду человеком.",0,54,0,0],["sd","(Обращаясь к хору, который перед этим только что выступил на Фимелу.)"],["v","А вы, со мной покинувшие Тмол,<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,55,1,0],["v","Вы, Лидии питомицы, подруги",0,56,0,0],["v","В пути и на стоянке, вы, тимпан",0,57,0,0],["v","Над головой фригийский поднимая,",0,58,0,0],["v","Подарок Реи-матери и мой,",0,59,0,0],["v","Столпитесь около дворца <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>:",0,60,0,1],["v","Пусть громкие удары соберут",0,60,0,0],["v","Сюда фиванцев. Я на Киферон",0,61,0,0],["v","Пойду теперь, к моим вакханкам новым,",0,62,0,0],["v","И в хороводы легкие вплетусь.",0,63,0,0],["v","⟨ВСТУПИТЕЛЬНАЯ ПЕСНЬ ХОРА⟩",0,64,0,0],["sp","Хор"],["sd","при произнесении 63 строки проходит вдоль параскений, спускается на фимелу (помост в орхестре, несколько ниже сцены) и располагается с левой стороны от зрителей, четырехугольником по пяти в ряд; средний в первом ряду — корифей. Флейтист (точнее кларнетист) предшествует хору и остается с ним на фимеле во все время пьесы. Хор состоит из 15 лидийских женщин: они в длинных одеждах, босые, на плечах небриды, голова увита плющом или тисом; в руках длинные тирсы в плюще или легкие короткие посохи; у иных, вместо тирса, в руках тимпан (род бубна). <span class=\"ch\" data-ch=\"dionis\">Дионис</span> по окончании пролога уходит направо. Хор поет в унисон. Первые восемь строк исполняет один корифей. Мимические движения, а может быть и плясовые, сопровождают эту вступительную песнь."],["str","Строфа I"],["v","Земли Азии, где вы?<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,65,2,0],["v","Тмол священный, ты покинут! Сладок труд мой.",0,65,0,0],["v","Я истому в славу <span class=\"ch\" data-ch=\"dionis\">Бромия</span> подъемлю,",0,66,0,0],["v","К богу <span class=\"ch\" data-ch=\"dionis\">Вакху</span> я взываю: Эвоэ!",0,67,2,0],["str","Антистрофа I"],["v","Прочь с дороги, с дороги!",0,68,2,0],["v","Скройтесь в домы, и уста благоговейно",0,69,0,0],["v","Пусть сомкнутся: <span class=\"ch\" data-ch=\"dionis\">Диониса</span> петь я буду,",0,70,0,1],["v","Как его везде я славлю и всегда.",0,71,2,0],["str","Строфа II"],["v","О, как ты счастлив, смертный,",0,72,0,0],["v","Если, в мире с богами,",0,73,0,0],["v","Таинства их познаешь ты,",0,74,0,0],["v","Если, на высях ликуя,",0,75,0,0],["v","<span class=\"ch\" data-ch=\"dionis\">Вакха</span> восторгов чистых",0,76,0,0],["v","Душу исполнишь робкую.",0,77,0,0],["v","Счастлив, если приобщен ты",0,78,2,0],["v","Оргий матери Кибелы;",0,79,2,0],["v","Если, тирсом потрясая,",0,80,2,1],["v","Плюща зеленью увенчан,",0,81,2,0],["v","В мире служишь <span class=\"ch\" data-ch=\"dionis\">Дионису</span>.",0,82,2,0],["v","Вперед, вакханки, вперед!",0,83,0,0],["v","Вы, бога и божьего сына,",0,84,0,0],["v","Домой <span class=\"ch\" data-ch=\"dionis\">Диониса</span> ведите!",0,85,0,0],["v","С гор Фригийских на стогна Эллады",0,86,0,0],["v","Отведите вы <span class=\"ch\" data-ch=\"dionis\">Вакха</span> домой.",0,87,2,0],["str","Антистрофа II"],["v","Грянули громы Зевса —",0,88,0,0],["v","Муки родов приспели:",0,89,0,0],["v","Не доносив, извергнула",0,90,0,1],["v","<span class=\"ch\" data-ch=\"dionis\">Бромия</span> мать из чрева",0,91,0,0],["v","И под ударом молний",0,92,0,0],["v","Кончила жизнь безвременно.",0,93,0,0],["v","Но извергнутого принял",0,94,2,0],["v","Зевс в свое немедля лоно",0,95,2,0],["v","И, тая от Геры сына,",0,96,2,0],["v","Он его в бедре искусно",0,97,2,0],["v","Золотой зашпилил пряжкой:",0,98,2,0],["v","Когда же приспел ему срок,",0,99,0,0],["v","Рогатого бога родил он,",0,100,0,1],["v","Из змеи он венок ему сделал:",0,101,0,0],["v","С той поры этой снедью звериной",0,102,0,0],["v","Обвивает менада чело.",0,103,2,0],["str","Строфа III"],["v","Вы, колыбель Семелы,",0,104,0,0],["v","Фивы, плющом венчайтесь!",0,105,0,0],["v","Нежной листвой оденьтесь,",0,106,0,0],["v","Пурпуром ягод тиса!",0,107,0,0],["v","<span class=\"ch\" data-ch=\"dionis\">Вакха</span> исполнись, город",0,108,0,0],["v","С зеленью дуба и ели!",0,110,0,1],["v","И белорунных кистей",0,111,2,0],["v","Больше на пестрой небриде нашей!",0,112,2,0],["v","Надменный тирс тебя сподобит <span class=\"ch\" data-ch=\"dionis\">Вакху</span>, —",0,113,0,0],["v","И вся страна запляшет за тобою,",0,114,0,0],["v","Где свои лики промчит <span class=\"ch\" data-ch=\"dionis\">Дионис</span>…",0,115,2,0],["v","В гору он мчится, а женщин толпа",0,116,2,0],["v","Ждет его там — не дождется.",0,117,2,0],["v","От станков их отбил <span class=\"ch\" data-ch=\"dionis\">Дионис</span>:",0,118,0,0],["v","Только <span class=\"ch\" data-ch=\"dionis\">Вакхом</span> и бредят.",0,119,0,0],["str","Антистрофа III"],["v","Крита юдоль святая,",0,120,0,1],["v","Мрачный приют Куретов,",0,121,0,0],["v","Зрел ты рожденье Зевса.",0,122,0,0],["v","С гребнем тройным на шлеме,",0,123,0,0],["v","Там Корибанты обруч",0,124,0,0],["v","Звонкой одели кожей.",0,125,0,0],["v","Дико тимпан загудел:",0,126,2,0],["v","С сладкими звуками слиться хотел",0,127,2,0],["v","Фригийских флейт; тимпан вручили Рее,",0,128,0,0],["v","Но стали петь под гул его вакханки.",0,129,0,0],["v","Рея сатирам его отдала:",0,130,2,1],["v","Звонкая кожа с ума их свела.<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,131,2,0],["v","Через два года на третий<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,132,2,0],["v","Бьют в тимпаны и пляшут они,",0,133,0,0],["v","Веселят <span class=\"ch\" data-ch=\"dionis\">Диониса</span>.",0,134,0,0],["str","Эпод"],["v","О, как я люблю <span class=\"ch\" data-ch=\"dionis\">Диониса</span>,<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,135,0,0],["v","Когда он один на горе",0,136,0,0],["v","От легкой дружины отстанет,",0,137,0,0],["v","В истоме на землю падет.",0,138,0,0],["v","Священной небридой одет он,",0,139,0,0],["v","Путь держит к Фригийским горам;",0,140,0,1],["v","Он хищника жаждал услады:",0,141,0,0],["v","За свежей козлиною кровью",0,142,2,0],["v","Гонялся сейчас.",0,143,2,0],["v","Но чу! Прозвучало: «О Вакх, эвоэ!»",0,144,0,0],["v","Млеком струится земля, и вином, и нектаром",0,145,0,0],["v","пчелиным,",1,145,0,0],["v","Смол благовонных дымом курится.",0,146,0,0],["v","Прянет тогда <span class=\"ch\" data-ch=\"dionis\">Дионис</span>…",0,147,2,0],["v","И вот уже носится вихрем:",0,148,0,0],["v","Он нежные кудри",0,150,2,1],["v","По ветру распустит.",0,150,2,0],["v","Вот факел горящий в горах замелькал",0,151,0,0],["v","На тирсе священном.",0,152,2,0],["v","И с вакхической песнью слились",0,152,0,0],["v","Призывные клики:",0,153,2,0],["v","\"Ко мне, мои вакханки,",0,154,2,0],["v","Ко мне, мои вакханки!",0,155,2,0],["v","Роскошный дар Пактола,",0,155,2,0],["v","Злаченые тимпаны",0,156,2,0],["v","Пусть тяжко загудят!",0,157,2,0],["v","Воспойте <span class=\"ch\" data-ch=\"dionis\">Диониса</span>,",0,157,2,0],["v","Ликующего бога,",0,158,2,0],["v","На свой фригийский лад!",0,159,2,0],["v","Нежной флейты священные звуки",0,160,0,1],["v","Пусть нагорный вам путь усладят!\"",0,161,0,0],["v","И призыв еще не смолкнул,",0,162,2,0],["v","А вакханка в быстром беге",0,163,2,0],["v","Рядом с <span class=\"ch\" data-ch=\"dionis\">Вакхом</span> уж несется:",0,164,2,0],["v","Точно в стаде жеребенок",0,165,2,0],["v","Подле матки скачет резвый.",0,166,2,0],["act","Действие первое","a2","I"],["scene","Явление второе","s2",2,2],["v","Сначала <span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>, потом <span class=\"ch\" data-ch=\"kadm\">Кадм</span>.",0,167,0,0],["sd","<span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span> входит справа, один; он — слепой и на сцену обыкновенно выступает с провожатым, но здесь на нем вакхический убор, и потому бог <span class=\"ch\" data-ch=\"dionis\">Дионис</span> невидимо поддерживает и направляет старца; поверх хитона на нем белая сетчатая шерстяная одежда предсказателей, но на голове вместо жреческой повязки зелень плюща; на плечах небрида, в руках тирс."],["sp","<span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>"],["dir","говорит громко, у ворот нет никого"],["v","Эй, кто там у ворот? поди скорей:",0,170,0,1],["v","Мне надо повидаться с <span class=\"ch\" data-ch=\"kadm\">Кадмом</span>,",0,170,0,0],["v","Что башнями наш город укрепил,",0,171,0,0],["v","Придя из стран Сидонских. Так пускай",0,172,0,0],["v","Ко мне он выйдет. Ты ему скажи,",0,173,0,0],["v","Что ждет его <span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>. Он, согбенный,",0,174,0,0],["v","И я, старик, сегодня мы должны",0,175,0,0],["v","Взять тирсы и, накинувши небриды,",0,176,0,0],["v","Плющом седые головы увить.",0,177,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["dir","он тоже в вакхическом уборе и по виду еще старше <span class=\"ch\" data-ch=\"tiresiy\">Тиресия</span>: выходит из дверей дворца"],["v","О, друг сладчайший! Выйти не успел я,",0,178,0,0],["v","Уж мудрого по голосу признал.",0,179,0,0],["v","Иду, иду. Смотри, как обрядился!",0,180,0,1],["v","Да, сколько в силах наших, я хочу",0,180,0,0],["v","Сегодня возвеличить <span class=\"ch\" data-ch=\"dionis\">Диониса</span>:",0,181,0,0],["v","Явленный бог — по дочери мне внук.",0,182,0,0],["v","Ты — человек умелый, мой <span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>,",0,183,0,0],["v","И я — старик вверяюсь старику:",0,183,0,0],["v","Не правда ль, ты укажешь, где плясать мне",0,184,0,0],["v","И где, остановившись, затрясти",0,185,0,0],["v","Седою головой? Я столько силы",0,186,0,0],["v","В себе почувствовал, что день и ночь",0,186,0,0],["v","Готов стучать о землю тирсом <span class=\"ch\" data-ch=\"dionis\">Вакха</span>:",0,187,0,0],["v","Веселье нам снимает годы с плеч.",0,188,0,0],["sp","<span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>"],["v","Со мною тоже, Кадм, — помолодел я",0,189,0,0],["v","И в хоровод вакхический войду.",0,190,0,1],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Но до горы не лучше ль нам доехать?",0,191,0,0],["sp","<span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>"],["v","А богу тем почет не уменьшим?",0,192,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Ну, так идем: моим заботам вверься.",0,193,0,0],["sp","<span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>"],["v","Сам бог, о Кадм, нам путь наш облегчит.",0,194,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","А мы одни — на игрище из граждан?",0,195,0,0],["sp","<span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>"],["v","Увы! разумных больше не нашлось.",0,196,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Что ж медлить далее, Тиресий, — руку!",0,197,0,0],["sp","<span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>"],["dir","протягивая перед собой руку"],["v","Кадм, вот моя рука, сплети ее с своей.",0,198,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Нет, презирать богов не мне — я смертен.",0,199,0,0],["sp","<span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>"],["v","Да, перед богом нечего мудрить:",0,200,0,1],["v","Предания отцов, как время, стары,",0,200,0,0],["v","И где та речь, что опровергнет их,",0,201,0,0],["v","Пусть в высях разума мудрец витает?",0,202,0,0],["v","Пожалуй, скажут вот: \"и как не стыдно?<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,203,0,0],["v","Старик плясать собрался и плющом",0,204,0,0],["v","Чело обвил!\" А разве где-нибудь",0,205,0,0],["v","Нам обозначил бог, что пляшет юный,",0,206,0,0],["v","А не старик в честь <span class=\"ch\" data-ch=\"dionis\">Вакха</span>. Нет, почет",0,207,0,0],["v","От всех равно приятен богу <span class=\"ch\" data-ch=\"dionis\">Вакху</span>:",0,208,0,0],["v","Своих поклонников не делит <span class=\"ch\" data-ch=\"dionis\">Дионис</span>.",0,209,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["dir","обращаясь к слепому"],["v","Тиресий, солнце для тебя не светит;",0,210,0,1],["v","Тебе заранее, что вижу, все скажу.",0,210,0,0],["sd","(Заметив подходящего <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>.)"],["v","Вот царь <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>, трон от меня приявший,",0,211,0,0],["v","Сюда спешит. Как озабочен он!",0,212,0,0],["v","Какие новости его смутили?",0,213,0,0],["scene","Явление третье","s3",2,3],["sd","Те же и <span class=\"ch\" data-ch=\"penfey\">Пенфей</span> входит слева. Это совсем молодой человек, с нежной растительностью на лице, огромного роста; на нем пурпурная накидка сверх пестрого хитона, на голове диадема, в руках скипетр; за ним свита, вооруженные слуги. Он, видимо, встревожен и сначала не замечает стариков."],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Едва успел вернуться я домой,",0,214,0,0],["v","Дурные вести слышу отовсюду,",0,215,0,0],["v","Нежданная постигла нас беда:",0,216,0,0],["v","Дома, детей фиванки побросали;",0,217,0,0],["v","В вакхическом безумии они",0,218,0,0],["v","Скитаются в горах, поросших лесом,",0,219,0,0],["v","И бога <span class=\"ch\" data-ch=\"dionis\">Диониса</span> — чт<em>о</em> за бог,",0,220,0,1],["v","Не знаю — почитают пляской.",0,220,0,0],["v","Среди их роев полные вином",0,221,0,0],["v","Стоят кратеры, а вакханки наши",0,222,0,0],["v","Тайком, поодиночке, в чащу леса",0,222,0,0],["v","Бегут с мужчиной ложе разделить.",0,223,0,0],["v","По виду, точно бы менады на служенье,",0,224,0,0],["v","Но Афродита им милей, чем <span class=\"ch\" data-ch=\"dionis\">Вакх</span>.",0,225,0,0],["v","Иных я уж поймал: связавши руки,",0,225,0,0],["v","В тюрьме теперь их люди стерегут.",0,226,0,0],["v","А тех, что нам покуда не попались,",0,227,0,0],["v","На Кифероне всех переловлю:",0,227,0,0],["v","Ин<em>о</em>, Агаву, что от Эхиона",0,228,0,0],["v","Меня родила, Актеона мать —",0,229,0,0],["v","Я разумею Автоною — крепко,",0,230,0,1],["v","В железо их велю я заковать,",0,230,0,0],["v","Авось тогда пройдет их беснованье.",0,231,0,0],["v","Да говорят, какой-то чародей",0,232,1,0],["v","Пожаловал из Лидии к нам в Фивы…<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,233,0,0],["v","Вся в золотистых кудрях голова",0,234,0,0],["v","И ароматных, сам с лица румяный,",0,235,0,0],["v","И чары Афродиты у него",0,235,0,0],["v","В глазах: обманщик дни и ночи",0,236,0,0],["v","С девицами проводит, — учит их",0,237,0,0],["v","Он оргиям ликующего бога…",0,238,0,0],["v","Ну, попадись он мне, — тогда стучать",0,239,0,0],["v","О землю тирсом, встряхивать кудрями",0,240,0,1],["v","Не долго будет — голову сниму.",0,240,0,0],["v","Он смеет богом <span class=\"ch\" data-ch=\"dionis\">Вакха</span> называть!",0,241,0,0],["v","В бедре у Зевса будто был зашит он.",0,242,0,0],["v","А между тем за выдуманный брак",0,243,0,0],["v","Семелу мать и <span class=\"ch\" data-ch=\"dionis\">Диониса</span> сына",0,244,0,0],["v","Огнем небесным Зевс испепелил —",0,245,0,0],["v","Все это знают, и неужто дерзкий,",0,245,0,0],["v","Кто б ни был он, хулой не заслужил",0,246,0,0],["v","Позорной петли.",0,247,0,0],["sd","(Оборачивается и видит стариков.)"],["v","Ба! Что вижу! Новость!",0,248,4,0],["v","Еще диковинка: <span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span> чудодей",0,249,0,0],["v","И матери моей отец, как будто на смех",0,250,0,1],["v","В небридах пестрых, с тирсами в руках",0,250,0,0],["v","Служить собрались <span class=\"ch\" data-ch=\"dionis\">Вакху</span>.",0,251,0,0],["sd","(Обращаясь к <span class=\"ch\" data-ch=\"kadm\">Кадму</span>.)"],["v","Дед, могу ли",0,252,4,0],["v","Я старость чтить, теряющую смысл.",0,253,0,0],["sd","(Несколько времени выжидает, но <span class=\"ch\" data-ch=\"kadm\">Кадм</span> стоит молча, тогда с нетерпеливым жестом.)"],["v","Да сбросишь ли ты плющ? От тирса руку",0,253,0,0],["v","Освободишь ли наконец, старик?",0,254,0,0],["sd","(Обращаясь к слепому, с насмешкой, потом с угрозой.)"],["v","Все ты, Тиресий, видно, снова хочешь,",0,255,0,0],["v","Вводя к фиванцам бога, погадать",0,256,0,0],["v","По птицам и за жертвы взять деньжонок.",0,256,0,0],["v","О, если б не седая голова",0,257,1,0],["v","Тебя спасала, посидел бы ты",0,258,0,0],["v","Теперь в оковах, там, среди вакханок,",0,259,0,0],["v","За оргии порочные, что вводишь!",0,260,0,1],["v","Нет, тот обряд, где женам подают",0,261,1,0],["v","Сок виноградный, чистым не признаю.",0,262,0,0],["sp","Хор"],["v","Безумец! ни богов, ни <span class=\"ch\" data-ch=\"kadm\">Кадма</span> чтить,",0,263,0,0],["v","Посеявшего колос земнородный,",0,264,0,0],["v","Не хочешь ты, и только род срамишь!",0,265,0,0],["sp","<span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>"],["dir","к <span class=\"ch\" data-ch=\"penfey\">Пенфею</span>, спокойно, с достоинством мудрого старца и прорицателя"],["v","Когда умен оратор, и предмет",0,266,1,0],["v","Искусно выбран им, не диво речью",0,267,1,0],["v","Ему пленить сердца. Но ты, Пенфей,",0,268,1,0],["v","На бойкость языка все возложил надежды:",0,269,1,0],["v","Твоим речам недостает ума.",0,270,1,1],["v","А вреден гражданин, коль, смелый и речистый,",0,270,1,0],["v","Он, власть имея, смыслом обделен.<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,271,1,0],["v","Смеешься ты над нашим новым богом:",0,272,2,0],["v","О, если бы внушить тебе я мог,",0,273,1,0],["v","Как будет славен он по всей Элладе!",0,274,1,0],["v","Послушай, юноша: две вещи в мире есть",0,275,1,0],["v","Для человека главные: Деметра",0,275,1,0],["v","— Или земля, как хочешь называй —",0,276,1,0],["v","Сухою пищею людей богиня кормит,",0,277,1,0],["v","Но не уступит ей Семелы сын:",0,278,1,0],["v","Придумал он питье из винограда",0,279,1,0],["v","И смертным дал — усладу всех скорбей.",0,280,1,1],["v","Когда несчастный соком винограда",0,280,1,0],["v","Пресытится, забвение и сон",0,281,1,0],["v","Забот дневных с души снимают тяжесть,",0,282,1,0],["v","И от страдания верней лекарства нет.",0,283,1,0],["v","Когда ж, сам бог, богам он отдается",0,283,1,0],["v","На возлияние, по милости его",0,284,1,0],["v","Со всех концов идет обилье к людям.",0,285,1,0],["v","Тебе смешно, Пенфей, что <span class=\"ch\" data-ch=\"dionis\">Вакх</span> зашит",0,286,1,0],["v","В бедре у Зевса был. А дело вот в чем:<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,286,1,0],["v","Когда из пламени небесного его",0,287,1,0],["v","Исхитил Зевс-родитель, этот отпрыск",0,288,1,0],["v","Божественный возвел он на Олимп,",0,289,1,0],["v","А Гера сбросить с неба захотела.",0,290,1,1],["v","Тогда придумал средство властный бог:",0,291,1,0],["v","Он сделал из небесного эфира",0,292,1,0],["v","Другого <span class=\"ch\" data-ch=\"dionis\">Диониса</span> и в борьбе",0,293,1,0],["v","Заложником тот призрак выдал Гере.",0,294,1,0],["v","Из h<em>o</em>meros с годами ho mer<em>o</em>s",0,295,1,0],["v","В устах народа вышло, и сложился",0,296,1,0],["v","Рассказ, что <span class=\"ch\" data-ch=\"dionis\">Вакх</span> в бедре зашит был Зевса.<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,297,1,0],["v","Наш <span class=\"ch\" data-ch=\"dionis\">Дионис</span> — и вещий бог: есть дар",0,298,1,0],["v","Пророчества в вакхическом безумье,",0,299,1,0],["v","И если в тело властно вступит бог,",0,300,1,1],["v","Уста безумцев исполняются вещаний.",0,300,1,0],["v","Арея он не чужд: когда порой",0,301,1,0],["v","Вооруженное и жадное сразиться",0,302,1,0],["v","Вдруг, жертвой страха сделавшись, бежит.",0,303,1,0],["v","Без боя войско — это чары <span class=\"ch\" data-ch=\"dionis\">Вакха</span>.",0,303,1,0],["sd","(Вдохновенно.)"],["v","Верь, будет день, когда в твоих глазах",0,304,2,0],["v","Двуглавую Парнасскую вершину,<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,305,1,0],["v","При свете факелов и потрясая тирсом,",0,306,1,0],["v","Стопою резвою <span class=\"ch\" data-ch=\"dionis\">Вакх</span> будет попирать,",0,306,1,0],["v","И будет всей Элладою прославлен",0,307,1,0],["v","Бог <span class=\"ch\" data-ch=\"dionis\">Дионис</span>.",0,308,1,0],["sd","(Опять в спокойном тоне.)"],["v","А ты, Пенфей, смирись:",0,309,1,0],["v","Не царь один повелевает людям, —",0,310,1,1],["v","И если ум твой поврежден, покинь",0,311,1,0],["v","Уверенность, что непреложно судишь.",0,312,1,0],["v","Нет, бога нового в страну приняв, почти",0,313,1,0],["v","Его и возлиянием, и пляской",0,314,1,0],["v","В венке. — А женщин скромности учить",0,315,1,0],["v","В делах любовных <span class=\"ch\" data-ch=\"dionis\">Дионис</span> не должен!",0,316,1,0],["v","Стыдливость — это их природный дар,",0,317,1,0],["v","И скромная не развратится в пляске.",0,318,1,0],["v","Когда народ толпится у дворца",0,319,2,0],["v","И граждане <span class=\"ch\" data-ch=\"penfey\">Пенфея</span> величают,",0,320,1,1],["v","Доволен ты. Вот так и <span class=\"ch\" data-ch=\"dionis\">Дионис</span>,",0,320,1,0],["v","Когда почтен вакхическою пляской.",0,321,1,0],["sd","(Как бы собираясь уходить.)"],["v","И так, покрывши голову плющом,",0,322,1,0],["v","На смех тебе, плясать мы с <span class=\"ch\" data-ch=\"kadm\">Кадмом</span> будем:",0,323,1,0],["v","В честь бога пляска и седым идет,",0,324,1,0],["v","И не склонил меня ты спорить с богом.",0,325,1,0],["sd","(Повышенным тоном, со сдержанной угрозой.)"],["v","Знай: ты больной безумец. Твой недуг",0,326,1,0],["v","Неизлечим, но жди — лекарство будет!",0,327,1,0],["sp","Хор"],["v","Приносят Фебу честь твои слова,",0,328,0,0],["v","И, славя <span class=\"ch\" data-ch=\"dionis\">Вакха</span>, старец, ты — разумен.",0,329,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["dir","ласково обращаясь к любимому внуку, которого считает несколько убежденным словами <span class=\"ch\" data-ch=\"tiresiy\">Тиресия</span>"],["v","Дитя мое, <span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span> дал совет",0,330,0,1],["v","Тебе благой: не преступай законов,",0,331,0,0],["v","Будь наш. Теперь не здраво судишь ты, —",0,332,0,0],["v","Ум затемнен в тебе пустым мечтаньем.",0,333,0,0],["v","Ну, хорошо: пусть он не <span class=\"ch\" data-ch=\"dionis\">Вакх</span>, все ж богом",0,334,0,0],["v","Признай его, <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>: ведь в этой лжи",0,335,0,0],["v","Семеле честь, в ней слава роду <span class=\"ch\" data-ch=\"kadm\">Кадма</span>.",0,336,0,0],["v","Перед тобой — несчастный Актеон:",0,337,0,0],["v","Псы хищные, ты помнишь, растерзали",0,338,0,0],["v","Его в лесу, когда он утверждал,",0,339,0,0],["v","Что в ловле он искусней Артемиды.",0,340,0,1],["v","Пока ты цел еще, Пенфей, плющом<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,340,0,0],["v","Дай увенчать тебя, восславим <span class=\"ch\" data-ch=\"dionis\">Вакха</span>!",0,341,0,0],["sd","(Протягивает к нему руку с плющом, взятым с тирса.)"],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","гневно, отстраняя руку <span class=\"ch\" data-ch=\"kadm\">Кадма</span>"],["v","Прочь руки, дед! Сам бражничать ступай",0,342,0,0],["v","И жалкой глупостью своей меня не пачкай!",0,343,0,0],["v","За слабоумие твое мне даст ответ",0,344,0,0],["v","Наставник твой.",0,345,0,0],["sd","(Обращаясь к одному из слуг.)"],["v","Эй, кто там, люди, живо",0,346,4,0],["v","Ступай на вышку старого, где птиц",0,347,0,0],["v","Он поджидает. Все разбей там ломом,",0,348,0,0],["v","Вверх дном поставь! Его повязки все",0,349,0,0],["v","На жертву кинь ветрам и вихрям буйным.",0,350,0,1],["sd","(В сторону, со злорадством.)"],["v","Злей кары он не выдумал бы сам!",0,350,0,0],["sd","(Посланный уходит направо, <span class=\"ch\" data-ch=\"penfey\">Пенфей</span> к другим.)"],["v","А вы, другие, выследите в Фивах",0,351,0,0],["v","Женоподобного лидийца, что принес",0,352,0,0],["v","Недуг неслыханный, пятная ложе брака, —",0,353,0,0],["v","А изловив, сюда его в цепях",0,354,0,0],["v","Ведите: пусть он, камнями побитый,",0,355,0,0],["v","Умрет, на горьком опыте узнав,",0,355,0,0],["v","Как здесь справляют праздники в честь <span class=\"ch\" data-ch=\"dionis\">Вакха</span>.",0,356,0,0],["v","Последние уходят направо.",0,357,0,0],["sp","<span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span>"],["dir","к <span class=\"ch\" data-ch=\"penfey\">Пенфею</span>"],["v","О нечестивец! что ты говоришь?",0,358,0,0],["v","Ты был помешан, а теперь взбесился.",0,359,0,0],["sd","(К <span class=\"ch\" data-ch=\"kadm\">Кадму</span>.)"],["v","Пойдем же, Кадм, молить, чтоб за него,",0,360,1,1],["v","За этого свирепого безумца,",0,360,0,0],["v","На город Фивы бог еще беды",0,361,0,0],["v","Нам не наслал. За мной, с плющом на тирсе",0,362,0,0],["v","Скорее в путь! а чтоб нам не упасть,",0,362,0,0],["v","Поддерживать мы, Кадм, друг друга будем:",0,363,0,0],["v","Два старика упавших — вид печальный…",0,364,0,0],["v","Там будь что будет, а должны служить",0,365,0,0],["v","Мы <span class=\"ch\" data-ch=\"dionis\">Дионису</span> богу, сыну Зевса.",0,365,0,0],["sd","(<span class=\"ch\" data-ch=\"kadm\">Кадм</span> во время последних слов <span class=\"ch\" data-ch=\"tiresiy\">Тиресия</span> берет его за руку, и они направляются к выходу. Уходя, <span class=\"ch\" data-ch=\"tiresiy\">Тиресий</span> приостанавливается и приподнимает свободную руку.)"],["v","Да, Кадм, смотри, чтобы <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>-горюн<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,366,0,0],["v","На дом твой славный не накликал горя:",0,367,0,0],["v","Не по гаданьям так я говорю,",0,367,0,0],["v","А по речам, что слышал от безумца.",0,368,0,0],["v","Уходят направо.",0,369,0,0],["sd","Пенфей, раздав приказания, уже не обращает внимания на дальнейшие слова стариков. Он остается на сцене, ожидая своих посланных; первый, посланный к <span class=\"ch\" data-ch=\"tiresiy\">Тиресию</span>, его не интересует: он ждет стражу, которая должна привести лидийца."],["scene","Первый музыкальный антракт","s4",2,4],["str","Строфа I"],["v","О, богиня из богинь,<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,370,1,1],["v","Правда, весь ты мир крылом",0,370,1,0],["v","Обвеваешь золотым!",0,371,1,0],["v","Неужели же <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>",0,372,1,0],["v","От очей твоих ушел",0,373,1,0],["v","И безбожный гнев укрыл,",0,374,1,0],["v","Гнев свой на <span class=\"ch\" data-ch=\"dionis\">Бромия</span>-бога,",0,375,0,0],["v","Средь венчанного пира",0,376,1,0],["v","Первого в сонме блаженных?",0,377,0,0],["v","Только у <span class=\"ch\" data-ch=\"dionis\">Вакха</span> и дела:",0,378,0,0],["v","В хороводы вакханок сплетать,",0,379,0,0],["v","Да под музыку флейты смеяться,",0,380,0,1],["v","Да из сердца гнать думы, когда",0,381,0,0],["v","Подают за трапезой богов",0,382,0,0],["v","Виноградную влагу,",0,383,0,0],["v","Или на плющом венчанных пирах",0,384,0,0],["v","Чаша на вежды людские дремоту наводит.",0,385,0,0],["str","Антистрофа I"],["v","Злоречивым без узды,",0,386,1,0],["v","Нечестивым и глупцам",0,387,1,0],["v","Злой конец определен;",0,388,1,0],["v","А рассудок и покой",0,390,1,1],["v","Человека берегут:",0,390,1,0],["v","С ними жизнь его прочна.",0,391,1,0],["v","Держатся миром и домы:",0,392,0,0],["v","С хладной выси эфирной",0,393,2,0],["v","Видят разумного боги,",0,394,0,0],["v","Видят они нечестивца.",0,395,0,0],["v","Да и мудрость не в мудрость, когда",0,395,0,0],["v","Человек выше смертного смотрит:",0,396,0,0],["v","Век проходит, и время не ждет,",0,397,0,0],["v","А ты счастье роняешь из рук,",0,398,0,0],["v","За мечтою гоняясь!",0,399,1,0],["v","Нет, мудрецы мне такие всегда",0,400,0,1],["v","Кажутся или больными, иль просто глупцами.",0,401,0,0],["str","Строфа II"],["v","Зовет",0,402,1,0],["v","сердце Киприйский брег:",1,402,0,0],["v","Там царит Афродита;",0,403,1,0],["v","Любви",0,404,1,0],["v","боги летают там,",1,404,0,0],["v","Разум у смертных чаруют.",0,405,1,0],["v","Туда,",0,406,1,0],["v","где без дождей полны",1,406,0,0],["v","Воды Нила стоустого,",0,407,1,0],["v","Я за тобой бы умчалась, Вакх…",0,408,1,0],["v","Нет, ты открой мне обитель Муз,<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,409,0,0],["v","Где красотою цветут живой",0,410,0,1],["v","Славные склоны Олимпа:",0,411,0,0],["v","Туда уведи меня, Бромий,",0,412,0,0],["v","Там первый запой «Эвоэ»:",0,413,1,0],["v","Хариты живут там, летает Желанье,",0,414,0,0],["v","И для оргий вакханкам — свобода.",0,415,0,0],["str","Антистрофа II"],["v","Пиры,",0,416,1,0],["v","<span class=\"ch\" data-ch=\"dionis\">Вакху</span> угодны вы,",1,416,0,0],["v","Милы Зевсову сыну!",0,417,1,0],["v","Но мир —<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,418,1,0],["v","добрый податель благ,",1,418,0,0],["v","Общий кормилец — милее.",0,420,1,1],["v","Вина",0,421,1,0],["v","влагу усладную,",0,422,2,0],["v","Всех печалей забвение,",0,423,1,0],["v","Дал богачу он и бедному.",0,424,1,0],["v","Но ненавистен ему гордец,",0,425,0,0],["v","Кто без заботы не хочет жить",0,426,0,0],["v","Утром и милою ночью.",0,427,0,0],["v","От тех мудрецов горделивых",0,428,0,0],["v","Я ум свой подальше держу,",0,429,1,0],["v","Душою свободной всегда принимаю",0,430,0,1],["v","От толпы я обычай и веру.",0,431,0,0],["act","Действие второе","a3","II"],["scene","Явление четвертое","s5",3,5],["sd","Входят слуги <span class=\"ch\" data-ch=\"penfey\">Пенфея</span> и ведут <span class=\"ch\" data-ch=\"dionis\">Диониса</span>, со связанными за спиной руками; тирс он, однако, не выпустил даже из связанных рук. Он идет спокойно. Во время речи слуги <span class=\"ch\" data-ch=\"penfey\">Пенфей</span> стоит потупившись, рассказ он слушает невнимательно и только по временам украдкой взглядывает на <span class=\"ch\" data-ch=\"dionis\">Диониса</span>."],["sp","Слуга"],["v","Мы привели к тебе желанную добычу:",0,432,0,0],["v","Не попусту старались, царь <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>.",0,433,0,0],["v","А зверь хоть дикий, смирный нам попался,",0,434,0,0],["v","Бежать не думал, сам и руки дал",0,435,0,0],["v","«Вяжите, мол», и только все смеялся",0,436,0,0],["v","С лица ж румяного ничуть не побледнел.",0,437,0,0],["v","Себя связать он дал и увести нам,",0,440,0,1],["v","И я с почтением тогда ему сказал:",0,440,0,0],["v","\"Пришелец, не моя на это воля:",0,441,0,0],["v","Мой господин связать тебя велел\".",0,442,0,0],["v","А с теми, царь, вакханками, которых,",0,443,0,0],["v","Связавши раньше, запер ты в тюрьму,",0,443,0,0],["v","Случилось чудо: узы их распались,",0,444,0,0],["v","И убежали пленницы. Поди,",0,445,0,0],["v","Теперь опять они на воле скачут",0,446,0,0],["v","И в чащу леса <span class=\"ch\" data-ch=\"dionis\">Бромия</span> зовут.",0,446,0,0],["v","Никто не помогал им снять оковы,",0,447,0,0],["v","С дверей никто запоров не снимал.",0,448,0,0],["sd","(Немного помолчав, тихо, как бы в раздумье разводя руками.)"],["v","Да, этот человек немало в Фивы",0,449,0,0],["v","Принес чудес. А воля, царь, твоя.",0,450,0,1],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","поднимает голову, но ни на кого не смотрит, с усмешкой"],["v","Распутать руки пленнику. Хоть боек,",0,450,0,0],["v","А из моих сетей не убежит.",0,451,0,0],["sd","(Пока <span class=\"ch\" data-ch=\"dionis\">Диониса</span> развязывают, <span class=\"ch\" data-ch=\"penfey\">Пенфей</span> поворачивается к нему и с усмешкой и деланной небрежностью разглядывает его.)"],["v","Ну, дай взглянуть, каков ты. Ишь красавец,",0,452,0,0],["v","Как раз на женский вкус! а ведь для жен",0,453,0,0],["v","Ты в Фивы и пришел. Да, не в палестре,",0,454,0,0],["v","Конечно, локон нежный твой взращен,",0,455,0,0],["v","Что вдоль щеки лежит, соблазна полный,",0,456,0,0],["v","Не на припеке солнца, в холодке",0,457,0,0],["v","Ты кожу белую свою лелеял,",0,458,0,0],["v","Когда красой Киприду уловлял.",0,459,0,0],["v","Скажи, почтеннейший, откуда родом?",0,460,0,1],["sd","(<span class=\"ch\" data-ch=\"penfey\">Пенфей</span> предлагает дальнейшие свои вопросы отрывисто. <span class=\"ch\" data-ch=\"dionis\">Дионис</span> отвечает без замедления и спокойно, притом тем спокойнее, чем больше горячится <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>.)"],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Без пышных слов тебе отвечу я.",0,461,0,0],["v","Ты, может быть, слыхал про Тмол цветущий?",0,462,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Чт<em>о</em> город Сарды охватил кольцом?",0,463,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Оттуда я. Мне Лидия — отчизна.",0,464,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","А эти таинства, откуда ты их взял?",0,465,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Сам <span class=\"ch\" data-ch=\"dionis\">Дионис</span>, сын Зевса, посвятил нас.",0,466,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","с усмешкой"],["v","Что ж новых Зевс богов вам народил?",0,467,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Он здесь с Семелой сочетался браком.",0,468,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Тебе внушал во сне иль наяву?",0,469,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Лицом к лицу, — и оргии преподал.",0,470,0,1],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","В каком же роде оргии, скажи?",0,471,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Нет, для непосвященных это — тайна.",0,472,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","А польза в чем поклонникам от них?",0,473,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Узнать тебе нельзя, а интересно.",0,474,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Поклонников вербуешь ловко ты!",0,475,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Нет, оргии извергнут нечестивца.",0,476,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Каков же из себя он был, тот бог?",0,477,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Какой хотел, без наших указаний.",0,478,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","нетерпеливо"],["v","Опять виляешь. Дело говори!",0,479,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Глупцом невежде кажется и умный.",0,480,0,1],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Ты с этим богом прямо к нам пришел?",0,481,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Нет, варвары уж оргии справляют.",0,482,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Умом слабее эллинов они.",0,483,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Как в чем, — но в этом варвар выше грека.",0,484,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","А служите вы ночью или днем?",0,485,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Ночь лучше. Мрак имеет обаянье.<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,486,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Ловушка, чтобы женщин развращать…",0,487,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Как будто днем позорному нет места!",0,488,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","сердясь"],["v","За злые выдумки я накажу тебя.",0,489,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Сам богу за нечестие ответишь.",0,490,0,1],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Поклонник <span class=\"ch\" data-ch=\"dionis\">Вакха</span> дерзкий! ты речист.",0,491,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Да чем же ты грозишь мне? что придумал?",0,492,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Во-первых, локоны твои я остригу.",0,493,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Они священны, богу их ращу я.",0,494,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","не слушая"],["v","Затем, ты тирс из рук мне передашь.",0,495,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Сам отними. Мой тирс — от <span class=\"ch\" data-ch=\"dionis\">Диониса</span>.",0,496,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","не слушая <span class=\"ch\" data-ch=\"dionis\">Диониса</span>"],["v","Потом в тюрьму тебя мы заключим.",0,497,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","А бог отпустит, стоит пожелать мне.",0,498,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","В толпу вакханок прежде попади.<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,499,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Зачем? бог тут, — он видит, что терплю я.",0,500,0,1],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","с усмешкой"],["v","Ну, бога что-то подле не видать.",0,500,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["dir","внушительно"],["v","Он здесь, но нечестив ты — и не видишь.",0,501,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","кричит"],["v","Взять дерзкого! Он оскорбил царя.",0,502,0,0],["v","Слуги приближаются.",0,503,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["dir","еще внушительнее"],["v","Оставьте, говорю. Я — зрячий, вы — слепые.",0,504,0,0],["v","Слуги останавливаются в нерешимости.",0,505,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Вяжите, говорю. Я царь, а он в плену.",0,505,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["dir","смотрит в упор на <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>"],["v","Ты позабыл, что делаешь и кто ты!",0,506,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","в минутном смущении"],["v","Пенфей, <span class=\"ch\" data-ch=\"agava\">Агавы</span> сын от Эхиона.",0,507,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Пенфей!.. И имя то беду тебе сулит.",0,508,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","попадая в прежний тон"],["v","Вон, дерзкий. (К слугам.) Подле стойла крепче",0,509,0,0],["v","Его вы привяжите! Там темно:",0,510,0,1],["v","Пусть пляшет. А его пособниц, женщин,",0,510,0,0],["v","Что он с собой привел, я распродам",0,511,0,0],["v","Иль, отучив от глупого стучанья",0,512,0,0],["v","И кожаной той музыки, к станку",0,513,0,0],["v","Приставлю, — мне работницы годятся.",0,514,0,0],["sd","Во время его слов слуги связывают спокойно стоящего при этом <span class=\"ch\" data-ch=\"dionis\">Диониса</span>."],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Я ухожу, но знай, чему не быть,",0,515,0,0],["v","Тому не быть. Тебя же за глумленье",0,515,0,0],["v","Тот <span class=\"ch\" data-ch=\"dionis\">Дионис</span>, которого признать",0,516,0,0],["v","Ты не хотел, накажет. Бог — в оковах.",0,517,0,0],["v","Слуги уводят <span class=\"ch\" data-ch=\"dionis\">Диониса</span>. <span class=\"ch\" data-ch=\"penfey\">Пенфей</span> идет за ними.",0,518,0,0],["scene","Второй музыкальный антракт","s6",3,6],["str","Строфа"],["v","Здравствуй, Диркея,",0,519,2,0],["v","Ахелоя старца дочь,",0,520,0,1],["v","В блеске девственном богиня!",0,520,0,0],["v","Помнишь, ты когда-то в волны",0,521,0,0],["v","Семя Зевса приняла?<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,522,0,0],["v","Из огня он вырвал сына,",0,523,0,0],["v","Из бессмертного, и спрятал",0,524,0,0],["v","У себя в бедре, воскликнув:",0,525,0,0],["v","\"Дифирамб, мой сын, укройся<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,526,0,0],["v","Ты к отцу в мужское чрево!",0,527,2,0],["v","Будет день, — и Дифирамбом",0,528,2,0],["v","Звать тебя велю я Фивам\".",0,529,2,0],["v","А теперь, о дева-радость,",0,530,2,1],["v","Нет увенчанным приюта:",0,531,2,0],["v","Гонишь ты дружину <span class=\"ch\" data-ch=\"dionis\">Вакха</span>.",0,532,2,0],["v","Чем тебе я не угодна?",0,533,2,0],["v","Нет, клянусь усладой <span class=\"ch\" data-ch=\"dionis\">Вакха</span>,",0,534,0,0],["v","Пьяным соком винограда:",0,535,2,0],["v","Ты еще подумаешь о <span class=\"ch\" data-ch=\"dionis\">Вакхе</span>.",0,536,0,0],["str","Антистрофа"],["v","О, сколько гнева,",0,537,2,0],["v","Сколько гнева здесь явил",0,538,0,0],["v","Царь <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>, земли исчадье",0,539,0,0],["v","И змеиное отродье,",0,540,0,1],["v","Это семя Эхиона,<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,541,0,0],["v","Сына темного земли!",0,542,0,0],["v","Не похож на человека:",0,543,0,0],["v","Смертью он и кровью дышит,",0,544,0,0],["v","Как гигант в борьбе с богами.",0,545,0,0],["v","На дружину <span class=\"ch\" data-ch=\"dionis\">Вакха</span> узы",0,546,2,0],["v","Изготовил, в стены дома",0,547,2,0],["v","Моего вождя он спрятал,",0,548,2,0],["v","Держит связанным в темнице.",0,549,2,0],["v","Дионис, о чадо Зевса!",0,550,2,1],["v","Вещих слуг в горниле бедствий",0,551,2,0],["v","Неужели ты покинешь?",0,552,2,0],["v","Нет, о бог, спустись с Олимпа,",0,553,0,0],["v","Тирс колебля златоцветный,",0,554,2,0],["v","Укроти ты ярый гнев безумца!",0,555,0,0],["str","Эпод"],["v","Где теперь за желтым тирсом,<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,556,0,0],["v","Дионис, твой рой летит?",0,557,0,0],["v","По лугам ли тучной Нисы,",0,558,0,0],["v","Иль Парнас тебя взманил,",0,559,0,0],["v","Или заросли лесные",0,560,2,1],["v","По ущелиям Олимпа,",0,560,2,0],["v","Где игру Орфея слушать<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,561,2,0],["v","Звери дикие стекались,",0,562,2,0],["v","И сходили с мест деревья?",0,563,2,0],["v","О Пиерия, ликуй!",0,564,2,0],["v","Эвий чтит тебя и гибких,",0,565,2,0],["v","Извивающихся в пляске,",0,566,2,0],["v","Он ведет к тебе вакханок.",0,567,2,0],["v","Только две реки пройдет он:",0,568,0,0],["v","Прежде будет быстрый Аксий,",0,569,0,0],["v","А потом, людей кормилец,",0,570,0,1],["v","Всю страну обогативший,",0,570,0,0],["v","Будет Лидий чистой влагой",0,571,0,0],["v","Разливаться по лугам.",0,572,0,0],["v","Что за кони там пасутся!",0,573,0,0],["act","Действие третье","a4","III"],["scene","Явление пятое","s7",4,7],["sd","На сцене — никого. Хор на помосте разделился на два полухория, по 7 человек. Корифей стал отдельно, ближе к сцене. За сценой тревожная суета. Слышны подземные удары. Фасад дворца колеблется. Огонь загорается на капище Семелы. Смятение охватывает женщин."],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["dir","за сценой"],["v","И-о!",0,574,2,0],["v","Слушайте голос мой, слушайте,<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,575,0,0],["v","Женщины, женщины!",0,576,0,0],["sp","Первое полухорие"],["v","Кто это? Чей",0,577,0,0],["v","Голос зовет меня? кликом вакхическим",0,578,2,0],["v","Кто зовет?",0,579,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","И-о! и-о! снова взываю.",0,580,0,1],["v","Я — сын Семелы и Зевса.",0,580,0,0],["sp","Второе полухорие"],["v","И-о! и-о!",0,581,2,0],["v","Царь ты наш радостный,",0,582,0,0],["v","О, поспеши",0,583,2,0],["v","В наш хоровод,",0,584,2,0],["v","Бромий, мы ждем тебя!",0,585,0,0],["sp","Корифей"],["v","Ай! ай!",0,585,0,0],["v","Где я стою? земля дрожит…",0,586,2,0],["v","Силы небесные!",0,587,3,0],["v","Весь на куски дворец сейчас рассыплется…",0,588,2,0],["v","То бог <span class=\"ch\" data-ch=\"dionis\">Дионис</span> в чертоги вступил.",0,589,0,0],["v","Вы славьте его!",0,590,0,0],["sp","Хор"],["v","Слава тебе!",1,590,0,1],["sp","Первое полухорие"],["v","Видишь: расходятся балки из мрамора,",0,590,0,0],["v","И из дворца сейчас",0,591,2,0],["v","<span class=\"ch\" data-ch=\"dionis\">Вакха</span> раздастся победный клик.",0,592,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["dir","за сценой"],["v","Факел зажги ты у молнии Зевсовой!",0,593,0,0],["v","Ты поджигай дворец, ты поджигай чертог!",0,594,0,0],["sp","Второе полухорие"],["v","Ах!",0,595,2,0],["v","Видишь, видишь ты пламя…",0,595,0,0],["v","Вот на гробе Семелы:",0,596,0,0],["v","Молния Зевса",0,597,2,0],["v","Пала стрелою там,",0,598,0,0],["v","Пламя зажгла.",0,599,2,0],["sp","Корифей"],["v","В прах упадите, менады дрожащие,",0,600,0,1],["v","Телом дрожащим в прах!",0,600,2,0],["v","Хоревты падают ниц.",0,601,0,0],["v","Царь ваш в чертоги несет разрушенье,",0,602,0,0],["v","Зевса великого сын.",0,603,2,0],["scene","Явление шестое","s8",4,8],["sd","Землетрясение утихло. Следы разрушения скрыты от глаз зрителей: фасад уцелел. Из дворца выходит <span class=\"ch\" data-ch=\"dionis\">Дионис</span> в том виде, в котором являлся раньше. Вид рабского, азиатского страха его поклонниц, поверженных ниц, ему не совсем приятен."],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Жены Азии! Вы трепетом объяты,<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,604,0,0],["v","Пали ниц вы и прониклись силой <span class=\"ch\" data-ch=\"dionis\">Вакха</span>,",0,605,0,0],["v","Когда дом он рушил. Но дерзайте,",0,605,0,0],["v","Поднимитесь и покиньте трепет!",0,606,0,0],["v","Хоревты поднимаются.",0,607,0,0],["sp","Хор"],["dir","с движением к <span class=\"ch\" data-ch=\"dionis\">Дионису</span>"],["v","Свет возлюбленный! Ты радость вакханалий",0,608,0,0],["v","Возвращаешь брошенной менаде.",0,609,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Духом пали вы, о женщины, покуда",0,610,0,1],["v","Отводил в тюрьму меня <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>?",0,610,0,0],["sp","Хор"],["v","Да ведь ты — одна моя защита…",0,611,0,0],["v","Как спастись-то удалось тебе?",0,612,2,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Спас я сам себя, без затруднений.",0,613,0,0],["sp","Хор"],["v","Разве рук тебе он не связал?",0,613,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Над глупцом смеялся я: все время",0,614,0,0],["v","Он меня вязал в воображенье,",0,615,0,0],["v","А на деле пальцем не коснулся.",0,616,0,0],["v","Подле стойла, где мне полагалось",0,616,0,0],["v","В заключенье быть, нашел быка он.",0,617,0,0],["v","Вот быку-то на ноги и начал",0,618,0,0],["v","Петли он накидывать, от гнева",0,619,0,0],["v","Задыхаясь, сам в поту, все губы",0,620,0,1],["v","Искусал он в кровь, — а на безумца,",0,620,0,0],["v","Тут же сидя, я глядел спокойно.",0,621,0,0],["v","В это время бог потряс чертоги",0,622,0,0],["v","И огонь на гробе матери зажег.",0,623,0,0],["v","Увидал <span class=\"ch\" data-ch=\"penfey\">Пенфей</span> и испугался.",0,624,0,0],["v","Думал, что пожар. И вот рабам он",0,625,0,0],["v","Приказал таскать воды, работу",0,625,0,0],["v","Задал всем, но даром труд пропал.",0,626,0,0],["v","Вдруг блеснула мысль, что убежал я.",0,627,0,0],["v","Тут во двор с мечом бежит <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>…",0,628,0,0],["v","И, должно быть, <span class=\"ch\" data-ch=\"dionis\">Бромий</span> из эфира",0,629,0,0],["v","Сделал призрак мой. Я вижу, что <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>",0,630,0,1],["v","Выскочил и тычет в воздух, словно",0,630,0,0],["v","Горло колет… <span class=\"ch\" data-ch=\"dionis\">Вакх</span> на том не кончил:",0,631,0,0],["v","Рушит дом он — весь чертог в обломках:",0,632,0,0],["v","«Вот тебе, Пенфей, мои оковы».",0,632,0,0],["v","Меч из рук роняя, обессилен,",0,633,0,0],["v","Падает <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>. — Так вот что значит",0,634,0,0],["v","Смертному дерзать на битву с богом!",0,635,0,0],["v","К вам тогда я ухожу спокойно:",0,635,0,0],["v","О <span class=\"ch\" data-ch=\"penfey\">Пенфее</span> думы больше нету.",0,636,0,0],["v","За стеной — стук ⟨шагов⟩ <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>.",0,637,0,0],["v","Но шаги мне слышатся: стучит",0,637,0,0],["v","За стеной подошва: чу… подходит.",0,638,0,0],["v","Что-то нам теперь <span class=\"ch\" data-ch=\"penfey\">Пенфей</span> расскажет?",0,639,0,0],["v","Гнев его перенесу шутя:",0,640,0,1],["v","Мудрый должен быть всегда спокоен.",0,641,0,0],["scene","Явление седьмое","s9",4,9],["sd","Из дворца выходит <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>, задумчивый, без оружия, за ним свита. Сначала он не замечает <span class=\"ch\" data-ch=\"dionis\">Диониса</span>."],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Со мной беда: бежал тот чужестранец,",0,642,0,0],["v","Которого я только что связал.",0,643,0,0],["sd","(Увидав <span class=\"ch\" data-ch=\"dionis\">Диониса</span>, наскакивает на него.)"],["v","Ба! что я вижу?",0,644,2,0],["v","Как за стеною мог ты очутиться?",0,645,0,0],["v","Да говори ж, как вышел? что молчишь?",0,646,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["dir","слегка отстраняет его"],["v","Останови свой гнев — иди спокойно!",0,647,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","не слушая"],["v","Как ты ушел, как узы мог ты снять?",0,648,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Я говорил тебе: меня развяжут.",0,649,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Развяжет кто? Еще что сочинишь?",0,650,0,1],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Тот, кто лозу дает нам с виноградом.",0,651,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","В твоих устах звучит хулой и благо.<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,652,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","А сколько благ таких он вам принес!",0,653,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Эй! запереть ворота городские.",0,654,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Зачем? стене ль остановить богов?",0,655,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","с усмешкой"],["v","Мудрец, мудрец, а тут ума не стало.",0,656,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Мне верно служит мой природный ум…",0,657,0,0],["v","Я не уйду… а вот смотри-ка лучше:",0,658,0,0],["v","С горы к тебе — какой-то человек…",0,659,0,0],["sd","Последними словами <span class=\"ch\" data-ch=\"dionis\">Дионис</span> обращает внимание царя на новое лицо, пастуха с Киферона."],["scene","Явление восьмое","s10",4,10],["sd","Те же и вестник (приходит слева, с Киферона). Поверх короткого хитона на нем бурка, на голове шапка; волосы белые, гладкие, лоб в морщинах, грубые черты и толстый нос, борода с проседью. Он обращается к <span class=\"ch\" data-ch=\"penfey\">Пенфею</span>."],["v","Пенфей, владыка над землей фиванской!",0,660,0,1],["v","К тебе пришел я с Киферона: там",0,660,0,0],["v","Блестящий снег не тает в белых хлопьях.",0,661,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Пришел зачем? по делу по какому?",0,662,0,0],["sp","Вестник"],["v","Поведать про божественных менад:",0,663,0,0],["v","В безумном беге белыми ногами",0,664,0,0],["v","Они мелькают, и чудес немало,",0,665,0,0],["v","Каких чудес я нагляделся, царь.",0,666,0,0],["v","Тебе и городу рассказ мой да поможет!",0,667,0,0],["v","Но прежде мне хотелось бы узнать,",0,668,0,0],["v","Могу я говорить свободно, или речь мне",0,669,0,0],["v","Посдерживать? Ты на решенья скор,",0,670,0,1],["v","Гневлив и самовластен, и мне страшно.",0,671,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Все говори — в ответ не попадешь;",0,672,0,0],["v","И знай при том: чем больше про вакханок",0,673,0,0],["v","Наскажешь ужасов, тем я сильней казню",0,674,0,0],["v","Вот этого, внушившего им чары.",0,675,0,0],["sd","(Указывая на <span class=\"ch\" data-ch=\"dionis\">Диониса</span>.)"],["sp","Вестник"],["v","В тот час, как солнца первые лучи",0,676,0,0],["v","Греть начинают землю, полегоньку",0,677,0,0],["v","Быков на пастбище я в гору гнал, смотрю —",0,678,0,0],["v","Передо мной из женщин три дружины.",0,680,0,1],["v","В одной заметил Автоною я, в другой",0,681,0,0],["v","<span class=\"ch\" data-ch=\"agava\">Агава</span>-мать царила, в третьей Ино.",0,682,0,0],["v","Но спали женщины, раскинувшись свободно,",0,683,0,0],["v","Под спину веток ели подложив",0,684,0,0],["v","Или в листве дубовой утопая…",0,685,0,0],["v","И чинно как! а ты-то уверял,",0,686,0,0],["v","Что, опьяненные вином и звуком флейты,",0,687,0,0],["v","Они по зарослям глухим Киприду ловят…",0,688,0,0],["v","Но вот, средь стана спящего вскочив,",0,689,1,0],["v","<span class=\"ch\" data-ch=\"agava\">Агава</span>-мать их зычным криком будит!",0,690,0,1],["v","Она заслышала мычанье наших стад.",0,690,0,0],["v","И, легкий сон сгоняя с вежд, вскочили",0,691,0,0],["v","Вакханки на ноги — все чудо как скромны:",0,692,0,0],["v","Старухи, жены молодые и девицы…",0,693,0,0],["v","Сначала кудри распускают по плечам,",0,694,0,0],["v","А у кого небрида распустилась,",0,695,0,0],["v","Те подвязать спешат и пестрой лани",0,696,0,0],["v","Опять покров змеею подпоясать.",0,697,0,0],["v","И змеи им при этом лижут щеки.",0,698,0,0],["v","Те взяли на руки волчонка, сосунка",0,699,0,0],["v","От лани и к грудям их приложили",0,700,0,1],["v","Набухшим. Видно, матери детей",0,700,0,0],["v","Новорожденных бросили. Венками",0,701,0,0],["v","Из плюща, из листвы дубовой или тиса",0,702,0,0],["v","Цветущего украсились потом.",0,703,0,0],["v","Вот тирс берет одна и ударяет",0,704,0,0],["v","Им о скалу. Оттуда чистый ключ",0,705,0,0],["v","Воды струится. В землю тирс воткнула",0,706,0,0],["v","Другая — бог вина источник дал,",0,707,0,0],["v","А кто хотел напиться белой влаги,",0,708,0,0],["v","Так стоило лишь землю поскоблить",0,709,0,0],["v","Концами пальцев — молоко лилося.",0,710,0,1],["v","С плюща на тирсах капал сладкий мед…",0,710,0,0],["v","Бранишь ты <span class=\"ch\" data-ch=\"dionis\">Вакха</span>, царь, но, раз увидев",0,711,0,0],["v","Все это, ты молился бы ему.",0,712,0,0],["v","Мы, пастухи коровьи и овечьи,",0,713,1,0],["v","Сошлись тогда, и все наперерыв",0,714,0,0],["v","О чудесах невиданных судили…",0,715,0,0],["v","Бывалый человек нашелся тут",0,716,0,0],["v","И мастер говорить — мы стали слушать,",0,717,0,0],["v","И вот что он сказал нам: \"Пастухи,",0,718,0,0],["v","Священных высей жители, давайте",0,719,0,0],["v","Похитим с игрища <span class=\"ch\" data-ch=\"agava\">Агаву</span>, мать царя!",0,720,0,1],["v","Мы угодим владыке\". Тут, конечно,",0,720,0,0],["v","Все согласились. В зелени кустов",0,721,0,0],["v","Устроили засаду, притаившись",0,722,0,0],["v","Сидим, — и вот в условный час",0,723,0,0],["v","Под взмахи тирсов игрище открылось,",0,724,0,0],["v","И в голос стали жены <span class=\"ch\" data-ch=\"dionis\">Вакха</span> звать.",0,725,0,0],["v","Все ликовало с ними — горы, звери,",0,726,0,0],["v","От топота задвигалась земля.",0,727,0,0],["v","Случись, что около меня в своем раденье",0,728,0,0],["v","<span class=\"ch\" data-ch=\"agava\">Агава</span> очутилась, чтоб схватить",0,729,0,0],["v","Ее, я выскочил — и тем открыл засаду.",0,730,0,1],["v","И — их! закричала — \"Борзые, за мной,",0,731,0,0],["v","За мною, быстрые! менад мужчины ловят:",0,732,0,0],["v","Тирс в руки, борзые, и все, и все — за мной!\"",0,733,0,0],["v","Бегом едва спаслись мы от вакханок;",0,734,0,0],["v","А то бы разорвали. Там стада",0,735,0,0],["v","У нас паслись, так с голыми руками",0,736,0,0],["v","На них менады бросились. Корову",0,737,0,0],["v","С набрякшим вымем и мычащую волочат.",0,738,0,0],["v","Другие нетелей рвут на куски. Там бок,",0,739,0,0],["v","Посмотришь, вырванный. Там пара ног передних",0,740,0,1],["v","На землю брошена, и свесилось с ветвей",0,741,0,0],["v","Сосновых мясо, и сочится кровью.",0,742,0,0],["v","Быки — обидчики, что в ярости, бывало,",0,743,0,0],["v","Пускали в ход рога, повержены лежат:",0,744,0,0],["v","Их тысячи свалили рук девичьих.",0,745,0,0],["v","Ты б царским глазом не успел моргнуть,",0,746,0,0],["v","Так быстро кожу с мяса там сдирали.",0,747,0,0],["v","Но вот снялись вакханки: легче птицы",0,748,1,0],["v","Бегут на берега Асопа, в те поля,<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,750,0,1],["v","Что свой дают фиванцам тучный колос,",0,750,0,0],["v","В Эритры, в Гисии, за Киферонский склон, —",0,751,0,0],["v","Они несут повсюду разрушенье:",0,752,0,0],["v","Я видел, как они, детей украв,",0,753,0,0],["v","Их на плечах несли, не подвязавши,",0,754,0,0],["v","И на землю не падали малютки.",0,755,0,0],["v",". . . . . . . . . . . . . . . . . .<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,756,0,0],["v","Ни меди, ни железа, — а на кудрях",0,757,0,0],["v","У них огонь горел и их не жег.",0,758,0,0],["v","Потоком уносимые пытались",0,759,1,0],["v","Оружие поднять. И вот то диво, царь,",0,760,0,1],["v","Их дротик хоть бы раз вакханку ранил,",0,761,0,0],["v","Вакханка тирс поднимет, и бегут",0,762,0,0],["v","Мужчины — сколько раненых осталось!",0,763,0,0],["sd","(Таинственно, понизив голос.)"],["v","Менадам тут не смертный помогал.",0,764,0,0],["v","Но вот туда вернулися вакханки,",0,765,1,0],["v","Где бог для них источники открыл.",0,766,0,0],["v","В прозрачной влаге смыли кровь, а змеи",0,767,0,0],["v","Лизали капли, щеки освежая.",0,768,0,0],["v","О, господин, кто б ни был этот бог,",0,769,1,0],["v","Но он — великий бог, прими его в наш город!",0,770,0,1],["v","Не знаю, так ли, только я слыхал,",0,770,0,0],["v","Что это он, на утешенье горю,",0,771,0,0],["v","Дал людям виноград, — а без вина",0,772,0,0],["v","Какая уж любовь, какая радость!",0,773,0,0],["sp","Хор"],["v","Перед лицом тирана говорить",0,774,0,0],["v","Слова свободные опасно, но скажу я:",0,775,0,0],["v","«Да, всех богов сильнее <span class=\"ch\" data-ch=\"dionis\">Дионис</span>».",0,776,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Вот и сюда кощунство, точно пламя",0,777,0,0],["v","Пожарное, подкралося. Для греков",0,778,0,0],["v","Какой позор!",0,779,0,0],["v","Но медлить поздно: (слуге) слушай,",1,779,0,0],["v","Ступай к Электриным воротам. Всем скажи,<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,780,0,1],["v","Кто носит щит тяжелый или конным",0,780,0,0],["v","Вступает в бой; кто зыблет легкий щит",0,781,0,0],["v","Иль лука тетиву в сраженье щиплет, —",0,782,0,0],["v","Всем объяви, что мы идем в поход",0,783,0,0],["v","Против менад. Какой еще беды,",0,784,0,0],["v","Когда над нами женщины глумятся?",0,785,0,0],["v","Посланный уходит.",0,785,0,0],["scene","Явление девятое","s11",4,11],["v","<span class=\"ch\" data-ch=\"dionis\">Дионис</span> и <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>.",0,786,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Пенфей, ты не хотел послушаться меня<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,787,0,0],["v","И груб ты был со мной. Но знай: не должен",0,788,0,0],["v","На бога поднимать руки ты, усмирись!",0,789,0,0],["v","Я говорю тебе, что <span class=\"ch\" data-ch=\"dionis\">Бромий</span> не потерпит,",0,790,0,1],["v","Чтоб трогали менад с ликующих вершин.",0,791,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Меня ты не удержишь. Будь доволен,",0,792,0,0],["v","Что ускользнул от уз, а то опять свяжу.",0,793,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","А лучше бы принес ты жертву <span class=\"ch\" data-ch=\"dionis\">Вакху</span>:",0,794,0,0],["v","Борьба смешна: ты — человек, он — бог.",0,795,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","За тем иду. В ущельях Киферона",0,796,0,0],["v","Я в жертву <span class=\"ch\" data-ch=\"dionis\">Вакху</span> самок перебью.",0,797,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Пенфей, прогонят вас, и — верх позора!",0,798,0,0],["v","Отступит перед тирсом медный щит.",0,799,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","сердясь"],["v","Вот навязался-то болтун беспутный:",0,800,0,1],["v","Ни отдыху, ни сроку не дает.",0,800,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Любезнейший! А дело можно сладить.",0,801,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Как сладить? У служанок стать рабом?",0,802,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Ты хочешь, я добуду их без боя.",0,803,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","недоумевая"],["v","Он что-то новое задумал, — вот беда!",0,804,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Чего боишься? Для тебя ж задумал.",0,805,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Тут просто заговор, чтоб оргии продлить.",0,806,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Да, с богом заговор: что верно — верно.",0,807,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","силясь попасть в прежний тон"],["v","Меч мне сюда! и перестань болтать!",0,808,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Ба!",0,809,0,0],["v","Хотел бы ты их посмотреть на месте?",0,810,0,1],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","как во сне"],["v","Еще бы! золотом я тысячу бы дал.",0,811,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Что ж посмотреть менад так загорелось?",0,812,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","с затаенной страстью в голосе"],["v","Позорно пьяными я видеть их хочу.",0,813,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Как? с радостью ты испытал бы горечь?",0,814,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","мечтательно"],["v","Я б под сосной там молча просидел.",0,815,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Ведь выследят, как ни таись, любезный.",0,816,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","в экстазе"],["v","Ты — прав. Туда открыто я пойду.",0,817,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Что ж? значит, в путь? вести тебя готов я.",0,818,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Веди скорей! Теряем время мы.",0,820,0,1],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Постой! сначала пеплос ты наденешь.<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,821,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Как, разве я перечисляюсь в жены?",0,822,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Нельзя иначе — мужа там убьют.",0,823,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Ты прав опять: хвалю твой ум и опыт.",0,824,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Искусство это дал мне <span class=\"ch\" data-ch=\"dionis\">Дионис</span>.",0,825,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Совет хорош, да как его исполнить?",0,826,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Там, во дворце, тебя одену я.",0,827,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Как? женщиной? мне, чужестранец, стыдно.",0,828,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Так, значит, видеть их ты расхотел?",0,829,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","немного подумав"],["v","А что ты мне надеть на тело скажешь?",0,830,0,1],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","С макушки волосы распустим подлинней…",0,831,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Потом… Какой наряд ты мне придумал?",0,832,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","По пяты — пеплос, митру — над челом…",0,833,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","К убору что-нибудь еще прибавишь?",0,834,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Да в руку — тирс, небриду спустим с плеч.",0,835,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","короткое молчание: в нем чувствуется душевная борьба"],["v","Нет, я не в силах женщиной одеться.",0,836,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","В сраженье с ними лучше кровь пролить?",0,837,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Ты прав, — разведки мне необходимы.",0,838,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Умней, чем лихо лихом прогонять.",0,839,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","А как пройти чрез Фивы незаметно?",0,840,0,1],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Я знаю путь. Мы пустырем пройдем.",0,841,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Все — лучше, чем глумление вакханок.",0,842,0,0],["sd","(Проводя рукой по лицу и поворачиваясь к главным воротам дворца.)"],["v","Войдем! здесь с мыслями никак не соберусь.",0,843,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","И то войдем. (В сторону.) Идет отлично дело.",0,844,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","силясь сохранить самообладание и рассудительность"],["v","Соображу, что лучше: воевать",0,845,0,0],["v","Или твоим последовать советам?",0,846,0,0],["sd","(Уходит во дворец.)"],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","О, женщины! в силки он сам идет,",0,847,0,0],["v","И ждет <span class=\"ch\" data-ch=\"penfey\">Пенфея</span> кара у вакханок.",0,848,0,0],["v","Ты близко, Дионис, и наказать",0,849,0,0],["v","Его поможешь. Легкое безумье",0,850,0,1],["v","Наслав, с ума его сведи! он не хотел",0,851,0,0],["v","В рассудке здравом женщиной одеться,",0,852,0,0],["v","Пускай с ума для этого сойдет.",0,853,0,0],["v","А за его недавние угрозы",0,854,0,0],["v","Посмешищем фиванцев станет он,",0,855,0,0],["v","Когда пойдет средь них в наряде женском.",0,856,0,0],["v","Пойду <span class=\"ch\" data-ch=\"penfey\">Пенфею</span> надевать убор,",0,857,0,0],["v","В котором он сойдет в чертог Аида,",0,858,0,0],["v","Руками матери убитый. <span class=\"ch\" data-ch=\"dionis\">Дионис</span>",0,859,0,0],["v","Ему себя покажет: бог суровый —",0,860,0,1],["v","Для гордых, а для кротких — нет добрей.",0,861,0,0],["sd","(Уходит во дворец.)"],["scene","Третий музыкальный антракт","s12",4,12],["sd","Припев поется всем хором, а строфа и антистрофа — полухориями."],["sp","Хор"],["str","Строфа"],["v","Милая ночь, придешь ли?<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,862,0,0],["v","<span class=\"ch\" data-ch=\"dionis\">Вакху</span> всю я тебя отдам,",0,863,0,0],["v","Пляске — белые ноги,",0,864,0,0],["v","Шею — росе студеной.",0,865,0,0],["v","Лань молодая усладе",0,866,0,0],["v","Луга зеленого рада.",0,867,0,0],["v","Вот из облавы вырвалась,",0,868,0,0],["v","Сеть миновала крепкую.",0,869,0,0],["v","Свистом охотник пускай теперь",0,870,0,1],["v","Гончих за ланью шлет.",0,871,0,0],["v","Ветер — у ней в ногах,",0,872,0,0],["v","В поле — раздолье.",0,873,0,0],["v","Берегом мчаться отрадно ей…",0,874,0,0],["v","И любо лани в чащу леса",0,875,2,0],["v","Подальше скрыться от людей.",0,876,2,0],["v","Когда ж над вражьей головой",0,877,0,0],["v","Держишь победную руку ты, —",0,878,0,0],["v","Это ль не мудрость?",0,879,0,0],["v","Дара прекраснее нет для тебя у богов.",0,880,0,1],["v","Жажду прекрасного дара!",0,880,0,0],["str","Антистрофа"],["v","Медленно, твердым шагом",0,881,0,0],["v","Божья сила к нам движется.",0,882,0,0],["v","Дерзких она карает,",0,883,0,0],["v","Тех, кто живет неправдой,",0,884,0,0],["v","Кто отвергает безумно",0,885,0,0],["v","Жертвы богам и моленья.",0,886,0,0],["v","За нечестивцем издали",0,887,0,0],["v","Зорко следят бессмертные:",0,888,0,0],["v","Казнь приближается тихо к ним",0,889,0,0],["v","С каждым мгновением.",0,890,0,1],["v","Веры не надо нам",0,891,0,0],["v","Лучше отцовской,",0,892,0,0],["v","Дорог старинный обычай нам;",0,893,0,0],["v","И то, что время освятило,",0,894,2,0],["v","Чт<em>о</em> бог нам дал, нельзя не чтить.",0,895,2,0],["v","Когда ж над вражьей головой",0,896,0,0],["v","Держишь победную руку ты, —",0,897,0,0],["v","Это ль не мудрость?",0,898,0,0],["v","Дара прекраснее нет для тебя у богов.",0,900,0,1],["v","Жажду прекрасного дара!",0,900,0,0],["str","Эпод"],["v","Счастлив ты, если в бурю",0,901,0,0],["v","В гавань вошел и спасся;",0,902,0,0],["v","Счастлив, и труд окончив.",0,903,0,0],["v","Властью и деньгами",0,904,0,0],["v","Разнятся смертные,",0,905,0,0],["v","Но всем в сердце положена",0,906,0,0],["v","Надежд сила безмерная.",0,907,0,0],["v","Одни счастьем венчаются,",0,908,0,0],["v","Другим нет исполнения,",0,909,0,0],["v","Кто день за днем без печали живет,",0,910,2,1],["v","Тот, по-моему, счастлив.",0,911,2,0],["act","Действие четвертое","a5","IV"],["scene","Явление десятое","s13",5,13],["sd","Из дворца сначала выходит <span class=\"ch\" data-ch=\"dionis\">Дионис</span> и, обращаясь к двери, из которой вышел, вызывает <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>."],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Ты, видеть запрещенное и делать",0,912,0,0],["v","В несчастной страсти ищущий <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>,",0,913,0,0],["v","Из дома выйди и явись менадой,",0,914,0,0],["v","В вакхическом уборе — как идешь",0,915,0,0],["v","Лазутчить мать и пляшущих вакханок!",0,916,0,0],["sd","Из дворца выходит <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>, одетый менадой; на его огромной фигуре неловко сидит женский наряд: локоны выбились из-под митры, подол висит неровно: в походке и движениях заметно что-то лихорадочное. Глаза блестят. Он перекладывает из руки в руку тирс."],["v","Как ты похож теперь на <span class=\"ch\" data-ch=\"kadm\">Кадма</span> дочь.",0,917,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","не слушая его, оглядывается вокруг с удивлением"],["v","Мне кажется, что вижу я два солнца",0,918,0,0],["v","И Фивы семивратные вдвойне.",0,919,0,0],["sd","(К <span class=\"ch\" data-ch=\"dionis\">Дионису</span>.)"],["v","Ты кажешься быком мне, чужестранец,",0,920,0,1],["v","Вон у тебя на голове рога.",0,921,0,0],["v","Так ты был зверь и раньше? Бык, бесспорно!",0,922,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","То божья милость снизошла, <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>.",0,923,0,0],["v","Ты видишь то, чт<em>о</em> должен был ты видеть.",0,924,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Кого ж тебе напоминаю я:",0,925,0,0],["v","Ин<em>о</em> или <span class=\"ch\" data-ch=\"agava\">Агава</span> пред тобою?",0,926,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Как будто на обеих я смотрю…",0,927,0,0],["v","Но, погоди, я локоны под митру",0,928,0,0],["v","Тебе убрал. Откуда ж эта прядь?",0,929,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Да выбилась. Я, знаешь, был в восторге",0,930,0,1],["v","И голову все вскидывал да гнул…",0,931,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Сейчас исправим. Я недаром взялся",0,932,0,0],["v","Тебе служить. Ну, голову прямей!",0,933,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Изволь. Я вещью сделался твоею.",0,934,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","И пояс распустился. Посмотри:",0,935,0,0],["v","Края у пеплоса не сходятся в подоле.",0,936,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","смотрит на подол своего платья"],["v","Не правда ли, что с правой стороны",0,937,0,0],["v","Волочится, с другой же все исправно?",0,938,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["dir","оправляя на нем платье"],["v","А вдруг менад ты скромными найдешь?",0,939,0,0],["v","Ведь для меня награды ты не сыщешь?",0,940,0,1],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","В какую руку тирс я должен взять,",0,941,0,0],["v","Чтобы казаться истинной вакханкой?",0,942,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Конечно, в правую, и правой же ногой",0,943,0,0],["v","Поддерживать. Ты изменился к благу.",0,944,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","в экстазе"],["v","Как думаешь, смогу ль я Киферон",0,945,0,0],["v","С вакханками взвалить себе на плечи?",0,946,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Да, если ты захочешь. Разум твой",0,947,0,0],["v","Был не здоров, теперь он настоящий.",0,948,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Рычаг возьмем, или рукой скалу",0,949,0,0],["v","Мне обхватить, или плечо подставить?",0,950,0,1],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Нет, пощади, Пенфей, обитель Муз,",0,951,0,0],["v","Приют, где Пан играет на свирели.",0,952,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","переходя к другой мечте, более сладострастной"],["v","Ну хорошо. Действительно, зачем",0,953,0,0],["v","Их силой брать? Пусть ель меня прикроет.",0,954,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","О да, тебя прикроет верный кров,",0,955,0,0],["v","Коль ты пойдешь подстерегать вакханок.",0,956,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Мне чудится, что птички уж сидят,",0,957,0,0],["v","Как в гнездышке, в сетях моих счастливых.",0,958,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Вот каковы разведки у тебя!",0,959,0,0],["v","Ты словишь, да… коль сам не будешь словлен.",0,960,0,1],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["dir","снова впадая в экстаз"],["v","По главным улицам теперь меня веди!",0,961,0,0],["v","На этот подвиг я один дерзаю.",0,962,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Да ты один за город пострадать",0,963,0,0],["v","Теперь идешь — ждет бой тебя достойный.",0,964,0,0],["v","Вперед! К спасению, Пенфей, тебя веду.",0,965,0,0],["v","Оттуда же доставит…",0,966,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Мать, конечно.",1,966,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Всем напоказ.",0,967,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["sd","О, я затем иду."],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Ты не пойдешь, снесут тебя.",0,968,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Вот роскошь!",1,968,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Мать — на руках…",0,969,0,0],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["v","Ты негу мне сулишь!",1,969,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Коль это нега.",0,970,0,1],["sp","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span>"],["sd","О, я стою славы. (Уходит направо.)"],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Ужасен замысел и страшен жребий твой,",0,971,0,0],["v","Но до небес дойдет <span class=\"ch\" data-ch=\"penfey\">Пенфея</span> слава.",0,972,0,0],["v","<span class=\"ch\" data-ch=\"agava\">Агава</span> с сестрами, вы, порожденье <span class=\"ch\" data-ch=\"kadm\">Кадма</span>!",0,973,1,0],["v","Вам в руки юношу <span class=\"ch\" data-ch=\"penfey\">Пенфея</span> предаю",0,974,0,0],["v","На страшный бой. Победа будет наша —",0,975,0,0],["v","<span class=\"ch\" data-ch=\"dionis\">Вакх</span> победит. А дальше — поглядим.<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,976,0,0],["sd","(Уходит за <span class=\"ch\" data-ch=\"penfey\">Пенфеем</span>.)"],["scene","Четвертый музыкальный антракт","s14",5,14],["sp","Хор"],["str","Строфа"],["v","На Киферон его вы, псицы Лиссы,",0,977,0,0],["v","Гоните, борзые! В челе дружин —",0,978,0,0],["v","Там <span class=\"ch\" data-ch=\"kadm\">Кадма</span> дочери.",0,979,0,0],["v","Под женским убором укрыться там мнит",0,980,0,1],["v","Лазутчик менад, безумный <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>.",0,981,0,0],["v","И первая мать с открытой скалы",0,982,0,0],["v","Увидит, как крадется он,",0,983,0,0],["v","И крикнет она:",0,984,0,0],["v","\"Смотрите: чужой",0,985,0,0],["v","Из Фив на Киферон наш, на Киферон пришел.",0,986,0,0],["v","Кто породил его? Крови не женской он.",0,987,0,0],["v","В нем львицы скорей порода видна,",0,988,0,0],["v","Ливийских горгон\".<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,990,0,1],["v","Гряди же ты, кара, с грозой, с мечом,",0,991,1,0],["v","И шею насквозь проколи",0,992,1,0],["v","Тому, кто суд и правду безбожный оскорбил,",0,993,1,0],["v","Пенфею, чаду праха!",0,994,1,0],["str","Антистрофа"],["v","Безумна ярость дикого Пентея,",0,995,0,0],["v","О Дионис, на оргии твои",0,996,0,0],["v","И Реи матери!",0,997,0,0],["v","Все рвется безумец на дерзкий бой",0,1000,0,1],["v","В борьбе роковой победу вкусить…",0,1001,0,0],["v","Нет, горя не знать",0,1002,0,0],["v","Дано лишь тому,",0,1003,0,0],["v","Кто божье оставил богам,",0,1004,0,0],["v","Кто сдержан умом",0,1005,0,0],["v","И скромен душой.",0,1006,0,0],["v","Что мудрость, коли счастья не может дать она?",0,1007,0,0],["v","Мне же отрадно чтить ночью и днем богов;",0,1008,0,0],["v","И если чего в законе их нет,",0,1010,0,1],["v","То чуждо и мне.",0,1010,0,0],["v","Гряди же ты, кара, с грозой, с мечом,",0,1011,1,0],["v","И шею насквозь проколи",0,1012,1,0],["v","Тому, кто суд и правду безбожный оскорбил,",0,1013,1,0],["v","Пенфею, чаду праха!",0,1014,1,0],["str","Эпод"],["v","Быком обернись, ты наш <span class=\"ch\" data-ch=\"dionis\">Вакх</span>, наш бог,",0,1015,0,0],["v","Явись многоглавым драконом,",0,1016,0,0],["v","Иль львом золотистым ты в очи метнись!",0,1017,0,0],["v","Лазутчик менад нацелил напасть",0,1018,0,0],["v","На стаю вакханок.",0,1019,1,0],["v","Приди же и петлю с улыбкой накинь",0,1020,0,1],["v","Безумцу на шею.",0,1021,1,0],["act","Действие пятое","a6","V"],["scene","Явление одиннадцатое","s15",6,15],["sd","Второй вестник (приходит со стороны Киферона — по виду подобен первому, хотя не пастух, а домашний слуга)"],["v","О дом, блиставший счастьем среди греков,",0,1022,0,0],["v","Дом <span class=\"ch\" data-ch=\"kadm\">Кадма</span> старого, который здесь, в полях",0,1023,0,0],["v","Ареевых, пожал посев змеиный, —",0,1024,0,0],["v","Я плачу над тобой, да, плачу, хоть и раб.",0,1025,0,0],["sp","Хор"],["v","Ты с Киферона? что-нибудь случилось?",0,1026,0,0],["sp","Вестник"],["v","Узнай! Царя <span class=\"ch\" data-ch=\"penfey\">Пенфея</span> больше нет.",0,1030,0,1],["sp","Хор"],["v","О <span class=\"ch\" data-ch=\"dionis\">Бромий</span> владыка! Слава великому богу!",0,1030,0,0],["sp","Вестник"],["v","Что слышу я? У нас несчастье в доме,",0,1031,0,0],["v","А ты ликуешь, женщина!",0,1032,0,0],["sp","Хор"],["v","Я варварской песнью восславила бога",0,1033,0,0],["v","За то, что не надо оков мне бояться.",0,1034,0,0],["v","Вестник",0,1035,4,0],["v","Так мужества не хватит в Фивах…",0,1035,0,0],["v",". . . . . . . . . . . . . . . . . .<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,1036,0,0],["sp","Хор"],["v","Мой повелитель — Дионис, сын Зевса,",0,1037,0,0],["v","Не Фивы, нет!",0,1038,2,0],["sp","Вестник"],["v","Пусть рада ты, но громко ликовать",0,1039,0,0],["v","Не надо, женщина, в виду чужого горя.",0,1040,0,1],["sp","Хор"],["v","А смертью он какой погиб, скажи,",0,1041,0,0],["v","Безумец злой, средь замыслов преступных?",0,1042,0,0],["sp","Вестник"],["v","Дворы фиванские оставив за собой,",0,1043,0,0],["v","Мы вышли на берег Асопа и в ущелья",0,1044,0,0],["v","Вступили: было двое нас — покойный",0,1045,0,0],["v","Мой господин и я, а впереди шел гость.",0,1046,0,0],["v","В лесную глушь сначала мы забрались",0,1047,0,0],["v","И сели там на травке, притаясь.",0,1048,0,0],["v","Старались не шуметь, едва шептали,",0,1049,0,0],["v","Чтоб не открыли зрителей они.",0,1050,0,1],["v","Глядим — лощина, а вокруг все скалы,",0,1050,0,0],["v","А в той лощине ели да ручьи;",0,1051,0,0],["v","Под елями, глядим, сидят менады",0,1052,0,0],["v","И все по сердцу делом заняты:",0,1053,0,0],["v","Те облетевший снова навивают",0,1054,0,0],["v","На тирсы плющ, а те между собой",0,1055,0,0],["v","Перекликаются вакхическим напевом —",0,1055,0,0],["v","Вот жеребята резвые порой,",0,1056,0,0],["v","Ярмо покинув, так зовут друг друга.",0,1057,0,0],["v","Но женщин царь несчастный не видал:",0,1058,0,0],["v","И так сказал тогда он: \"Чужестранец,",0,1059,0,0],["v","Мне этих самозванок не видать:",0,1060,0,1],["v","Вот если б на какой-нибудь пригорок",0,1060,0,0],["v","Мне влезть, с верхушки ели посмотреть,",0,1061,0,0],["v","Я разглядел бы хорошо бесстыдниц\".",0,1062,0,0],["v","И чудо первое тогда наш гость явил.",0,1063,0,0],["v","Была там ель, под облака верхушкой:",0,1064,1,0],["v","Вот он ее берет и тихо-тихо стал",0,1065,0,0],["v","Клонить к земле. Как гибкий лук круглится,",0,1066,0,0],["v","Или под циркулем — волнистая черта,",0,1067,0,0],["v","Так до земли, круглясь, она склонилась",0,1068,0,0],["v","В его руках — не человек то был.",0,1069,0,0],["v","И вот, на ветке усадив <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>,",0,1070,1,1],["v","Гость начал потихоньку ель пускать,",0,1070,0,0],["v","Он наблюдал, чтоб всадник не свалился.",0,1071,0,0],["v","И прянула вершиной ель в эфир,",0,1072,0,0],["v","А на хребте ее сидел несчастный.",0,1073,0,0],["v","И вышло так, что всадник на виду,",0,1074,0,0],["v","А вниз менад ему почти не видно.",0,1075,0,0],["v","Сначала не заметили его.",0,1075,1,0],["v","А я смотрю — уж гостя подле нету,",0,1076,0,0],["v","И вдруг какой-то голос зазвучал",0,1077,0,0],["v","Из синевы воздушной, будто <span class=\"ch\" data-ch=\"dionis\">Вакха</span>;",0,1078,0,0],["v","И мне слова послышались:",0,1079,0,0],["v","\"Юницы,",1,1079,0,0],["v","Я вам веду того, кто осмеял",0,1080,0,1],["v","Меня и оргии. Пусть дерзкий вам заплатит!\"",0,1080,0,0],["v","И засиял божественный огонь",0,1081,0,0],["v","Между землей и небом в это время.",0,1082,0,0],["v","Ни дуновенья ветра. Охватило",0,1083,1,0],["v","Безмолвие и мягкий луг, и лес,",0,1084,0,0],["v","И голоса звериные замолкли…",0,1085,0,0],["v","Но женщины не разобрали слов,",0,1086,0,0],["v","Насторожились только, озираясь.",0,1087,0,0],["v","И вот опять призыв его звучит. —",0,1088,0,0],["v","Тут <span class=\"ch\" data-ch=\"kadm\">Кадма</span> дочери признали голос бога",0,1089,0,0],["v","И с места прянули… И легче голубей",0,1090,0,1],["v","Они несутся в напряженном беге;",0,1090,0,0],["v","Агава, сестры с ней, другие следом,",0,1091,0,0],["v","И дуновенье бога вихрем мчит",0,1092,0,0],["v","Через ручьи вакханок и стремнины.",0,1093,0,0],["v","Вот господина моего они",0,1094,0,0],["v","Заметили на ели. По соседству",0,1095,0,0],["v","Утес нашли и камнями швырять",0,1096,0,0],["v","В него пошли; ветвями отбивался",0,1097,0,0],["v","Он, сколько мог. Там тирсы засвистали",0,1098,0,0],["v","По воздуху. Но в бедную мишень",0,1099,0,0],["v","Не удалось попасть им, как ни бились:",0,1100,0,1],["v","Уж очень высоко тогда сидел",0,1100,0,0],["v","Беспомощный <span class=\"ch\" data-ch=\"penfey\">Пенфей</span> на этой ели…",0,1101,0,0],["v","И вот они, набравши сучьев дуба,",0,1102,0,0],["v","Стараются (железа нет у них)",0,1103,0,0],["v","Ель отделить от корней — все напрасно.",0,1104,0,0],["v","Попытку бросили и эту. Стала мать",0,1105,0,0],["v","Тут говорить: \"Давайте станем кругом,",0,1105,0,0],["v","За дерево возьмемся — и авось",0,1106,0,0],["v","С вершины мы тогда достанем зверя,",0,1107,0,0],["v","Чтоб тайн священных он не разгласил\".",0,1108,0,0],["v","Без счету рук за ель тут ухватились",0,1109,1,0],["v","И вырвали с корнями… наверху",0,1110,0,1],["v","Сидевший падает на землю, испуская",0,1111,0,0],["v","Немолчно жалобы: он гибель увидал.",0,1112,0,0],["v","И вот всех прежде мать его, как жрица,",0,1113,1,0],["v","Бросается на жертву. Тут <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>",0,1114,0,0],["v","С волос срывает митру, чтоб признала",0,1115,0,0],["v","Свое дитя <span class=\"ch\" data-ch=\"agava\">Агава</span> и спасла",0,1116,0,0],["v","Несчастная; щеки касаясь с лаской,",0,1117,0,0],["v","Он говорит: \"О мама, это я,",0,1118,0,0],["v","Пенфей, тобой рожденный с Эхионом.",0,1119,0,0],["v","Ты пожалей меня и за ошибки",0,1120,0,1],["v","Свое дитя, родная, не губи!\"",0,1120,0,0],["v","Но он молил напрасно: губы пеной",0,1121,1,0],["v","У ней покрылись, дико взор блуждал, —",0,1122,0,0],["v","И рассуждать была она не в силах:",0,1123,0,0],["v","Во власти <span class=\"ch\" data-ch=\"dionis\">Вакха</span> вся тогда была.",0,1124,0,0],["v","Вот в обе руки левую берет",0,1125,1,0],["v","Злосчастного <span class=\"ch\" data-ch=\"penfey\">Пенфея</span> руку, крепко",0,1126,0,0],["v","В бок уперлась и… вырвала с плечом —",0,1127,0,0],["v","Не силою, а божьим изволеньем.",0,1128,0,0],["v","Ин<em>о</em> с другой напала стороны",0,1129,0,0],["v","И мясо рвет. Явилась Автоноя.",0,1130,0,1],["v","За ней толпа. О боги, что за крик",0,1130,0,0],["v","Тут поднялся! Стонал <span class=\"ch\" data-ch=\"penfey\">Пенфей</span> несчастный.",0,1131,0,0],["v","Пока дышал, и ликований женских",0,1132,0,0],["v","Носились клики. Руку тащит та,",0,1133,0,0],["v","А та ступню с сандалией, и тело",0,1134,0,0],["v","Рвут, обнажив, менады и кусками,",0,1135,0,0],["v","Как мячиком, безумные играют…",0,1136,0,0],["v","Разбросаны останки по скалам",0,1137,1,0],["v","Обрывистым, в глубокой чаще леса…",0,1138,0,0],["v","Где их сыскать? А голову его",0,1139,0,0],["v","Победную <span class=\"ch\" data-ch=\"agava\">Агава</span> захватила",0,1140,0,1],["v","Обеими руками, и на тирс",0,1140,0,0],["v","Воткнула — головой считая львиной;",0,1141,0,0],["v","Трофей по Киферону пронесла,",0,1142,0,0],["v","И вот, покинувши сестер и хороводы,",0,1143,1,0],["v","Уж здесь она, по городу идет,",0,1144,0,0],["v","Гордясь, безумная, добычей злополучной,",0,1145,0,0],["v","И <span class=\"ch\" data-ch=\"dionis\">Вакха</span> прославляет, что помог",0,1145,0,0],["v","В охоте, что ее венчал победой.",0,1146,0,0],["v","А всей-то и победы — только слезы.",0,1147,0,0],["v","Подальше от несчастной отойти,",0,1148,0,0],["v","Пока еще близ дома нет <span class=\"ch\" data-ch=\"agava\">Агавы</span>!",0,1149,0,0],["v","Да, скромность и служение богам —",0,1150,1,1],["v","Вот лучшее что есть, и кто сумеет",0,1150,0,0],["v","Всю жизнь блюсти их свято, тот мудрец.",0,1151,0,0],["sd","(Уходит в город.)"],["act","Исход","a7",""],["scene","Явление двенадцатое","s16",7,16],["sd","Пока на сцене никого нет, хор исполняет короткую плясовую песню."],["sp","Хор"],["v","Воспляшем в честь <span class=\"ch\" data-ch=\"dionis\">Вакха</span> — и слава ему!",0,1152,0,0],["v","Мы кликом восславим Пенфееву смерть.",0,1153,0,0],["v","Погиб <span class=\"ch\" data-ch=\"penfey\">Пенфей</span> — отродье",0,1154,3,0],["v","Ужасное змеи:",0,1155,3,0],["v","Он женщиной оделся,",0,1155,3,0],["v","За посох тирс он принял",0,1156,3,0],["v","И с ним в Аид сошел.",0,1157,3,0],["v","Шел бык перед <span class=\"ch\" data-ch=\"penfey\">Пенфеем</span>:",0,1158,3,0],["v","В беду его он вел…",0,1159,3,0],["v","А вы, менады Фив,",0,1160,0,1],["v","Вы гимн свой, славы полный,",0,1160,3,0],["v","Победный гимн свели",0,1161,3,0],["v","На стоны и на слезы.",0,1162,3,0],["v","О славный поединок,",0,1163,3,0],["v","Где матери рука",0,1164,3,0],["v","Багрится кровью сына!",0,1165,3,0],["v","Но вот спешит к Пенфееву дворцу",0,1166,0,0],["v","<span class=\"ch\" data-ch=\"agava\">Агава</span>-мать — безумный взор блуждает…",0,1167,0,0],["v","Твой пир готов, о Эвий, Эвоэ!",0,1168,0,0],["scene","Явление тринадцатое","s17",7,17],["sd","<span class=\"ch\" data-ch=\"agava\">Агава</span> является слева в сопровождении толпы вакханок. Она в вакхическом уборе, в митре и небриде, босая, а на тирсе у нее голова <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>, вся перепачканная в крови; она оглядывается во все стороны и, по-видимому, находится в сильнейшем возбуждении. Следуют строфа и антистрофа, образующие печальную песнь, так называемый коммос. Хор поделен на полухория; в строфе <span class=\"ch\" data-ch=\"agava\">Агава</span> переговаривается с одним парастатом (корифеем полухория), в антистрофе — с другим. <span class=\"ch\" data-ch=\"agava\">Агава</span> спешит и не договаривает. Она то и дело с улыбкой поглядывает на голову <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>, украшающую ее тирс."],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["sd","Строфа Вакханки Азии!"],["sp","Хор"],["sd","Что ты зовешь меня?"],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Несем с Киферона",0,1169,0,0],["v","Улов свой счастливый, трофей этот свежий,",0,1170,0,1],["v","Кисть плюща к чертогам.",0,1171,0,0],["sp","Хор"],["v","Я вижу трофей твой: приди и ликуй!",0,1172,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Его без сетей изловила…",0,1173,0,0],["v","Смотрите-ка: львенок.",0,1174,0,0],["v","Ведь можно узнать…",0,1175,0,0],["sp","Хор"],["v","В глуши, где-нибудь?",1,1175,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","О да, Киферон…",0,1176,0,0],["sp","Хор"],["v","Да что ж Киферон?",1,1176,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Убил — Киферон…",0,1177,0,0],["sp","Хор"],["v","А чья ж это добыча?",0,1178,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Я первая взяла.",1,1178,0,0],["sp","Хор"],["v","Счастливица <span class=\"ch\" data-ch=\"agava\">Агава</span>!",0,1180,0,1],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","В дружинах так зовусь…",1,1180,0,0],["sp","Хор"],["v","Одна ты?",0,1180,0,0],["v","<span class=\"ch\" data-ch=\"agava\">Агава</span>",0,1181,2,0],["v","Нет, Кадма…",0,1182,0,0],["sp","Хор"],["v","Что <span class=\"ch\" data-ch=\"kadm\">Кадма</span>?..",1,1182,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Отродье…",1,1182,0,0],["v","Те после меня, те после меня",0,1183,0,0],["v","За зверя взялися.",0,1184,0,0],["sp","Хор"],["v","Добыча на славу!",1,1184,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["sd","Антистрофа Приди ж, пируй со мной!"],["sp","Хор"],["sd","Пир-то где, горькая?"],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Детеныш-то молод:",0,1185,0,0],["v","Цветущий, красивый; волосики пухом",0,1186,0,0],["v","Лицо обрамляют.",0,1187,0,0],["sp","Хор"],["v","Зверь дикий, конечно: как много волос!",0,1188,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Да, бог наш охотник искусный,",0,1189,0,0],["v","И ловко менад он",0,1190,0,1],["v","На след наводил.",0,1190,0,0],["sp","Хор"],["v","Владыка — ловец!",0,1191,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Ты хвалишь его?",0,1192,0,0],["sp","Хор"],["v","Конечно, хвалю!",1,1192,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Фиванцы с тобой.",0,1193,0,0],["sp","Хор"],["v","Хоть сын по крайней мере…",0,1194,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Меня похвалит он.",1,1194,0,0],["sp","Хор"],["v","За взятую добычу…",0,1195,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Чт<em>о</em> львицей рождена.",1,1195,0,0],["sp","Хор"],["v","На славу…",0,1196,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["sd","Со славой…"],["sp","Хор"],["v","Гордишься?",0,1197,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Еще бы!..",1,1197,0,0],["v","Добычей такой, трофеем таким,",0,1198,0,0],["v","Всем Фивам на диво…",0,1199,0,0],["sp","Хор"],["v","Твой подвиг свершен.",1,1199,0,0],["v","Да покажи же гражданам, Агава,",0,1200,0,1],["v","Победную добычу, наконец.",0,1201,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Вы, жители твердынь фиванских славных,",0,1202,0,0],["v","Придите и любуйтесь! Вот — трофей!",0,1203,0,0],["v","Мы, <span class=\"ch\" data-ch=\"kadm\">Кадма</span> дочери, мы зверя изловили:",0,1204,0,0],["v","Тут дротик фессалийский ни при чем,",0,1205,0,0],["v","И схвачен зверь не сетью, а кистями",0,1206,0,0],["v","Рук наших белых. Не к чему теперь,",0,1207,0,0],["v","Оружием обвесившись, кичиться!",0,1208,0,0],["v","По крайней мере <em>мы</em> его рукой",0,1209,0,0],["v","И изловили, и на части тело",0,1210,0,1],["v","Разъяли без железа.",0,1210,0,0],["v","Где ж отец?",0,1211,2,0],["v","Что я не вижу с нами старца <span class=\"ch\" data-ch=\"kadm\">Кадма</span>?",0,1212,0,0],["v","И где <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>, мой сын? Пускай возьмет",0,1213,0,0],["v","Он лестницу покрепче, и к триглифу",0,1213,0,0],["v","Вот эту львиную он голову прибьет,",0,1214,0,0],["v","<em>Мою</em> добычу в нашей славной ловле.",0,1215,0,0],["scene","Явление четырнадцатое","s18",7,18],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["dir","является слева в сопровождении слуг, несущих на носилках окровавленные куски Пенфеева тела, кое-как сложенные. Вначале ни <span class=\"ch\" data-ch=\"agava\">Агава</span> не замечает его, ни он <span class=\"ch\" data-ch=\"agava\">Агавы</span>"],["v","Сюда несите свой печальный груз,",0,1216,0,0],["v","Прислужники, поставьте перед домом…",0,1216,0,0],["v","<span class=\"ch\" data-ch=\"penfey\">Пенфея</span> труп искать пришлось мне долго,",0,1217,0,0],["v","И по кускам его я подбирал:",0,1218,0,0],["v","В расщелинах глубоких Киферона,",0,1219,0,0],["v","В лесу дремучем долго я ходил.",0,1220,0,1],["v","Мы с игрища с <span class=\"ch\" data-ch=\"tiresiy\">Тиресием</span> обратно",0,1220,0,0],["v","Уж городом фиванским шли домой,",0,1221,0,0],["v","Когда рассказ ужасный мне поведал,",0,1222,0,0],["v","На что дерзнули дочери мои.",0,1223,0,0],["v","Я снова — на гору, и вот оттуда внука,",0,1224,0,0],["v","Менадами убитого, несу.",0,1225,0,0],["v","Я видел там несчастных сумасшедших:",0,1225,0,0],["v","Что Аристею сына принесла,",0,1226,0,0],["v","Мать Актеонову, с ней Ино в чаще леса.",0,1227,0,0],["v","А про <span class=\"ch\" data-ch=\"agava\">Агаву</span> кто-то мне сказал,",0,1228,0,0],["v","Что видел, как вакхической стопою",0,1229,0,0],["v","Она сюда ушла.",0,1230,0,1],["sd","(Оборачивается и видит <span class=\"ch\" data-ch=\"agava\">Агаву</span>.)"],["v","Был верен слух.",0,1230,4,0],["v","О зрелище печальное! О горе!",0,1231,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","тоже видит отца, но не видит трупа <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>; она обращается к <span class=\"ch\" data-ch=\"kadm\">Кадму</span>"],["v","Отец, гордись! Да, дочерей таких",0,1232,0,0],["v","Еще никто из смертных не посеял…",0,1233,0,0],["v","Ты сестрами гордись, но больше мной:",0,1234,0,0],["v","Ты знаешь, как я от станка шагнула?",0,1235,0,0],["v","Зверей, отец, руками я ловлю…",0,1236,0,0],["sd","(Протягивает ему голову на тирсе.)"],["v","Вот полюбуйся на мою добычу,",0,1237,0,0],["v","И пусть она украсит твой дворец.",0,1238,0,0],["v","Прими ее обеими руками",0,1239,0,0],["sd","(Протягивает <span class=\"ch\" data-ch=\"kadm\">Кадму</span> голову <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>, сняв ее с тирса.)"],["v","И, ловлей дочери гордясь, зови на пир",0,1240,0,1],["v","Друзей, старик. О, разве не блаженство",0,1241,0,0],["v","Вкушаешь ты от наших славных дел?",0,1242,0,0],["sd","Во время этой речи <span class=\"ch\" data-ch=\"kadm\">Кадм</span> молча смотрит на <span class=\"ch\" data-ch=\"agava\">Агаву</span>. Головы он не берет и не приближается к дочери."],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Ты, скорбь, которую не смеришь, не оглянешь:",0,1243,0,0],["v","Убили вы — вот дело жалких рук.",0,1244,0,0],["sd","(С горечью.)"],["v","И славную богам повергла жертву",0,1245,0,0],["v","Ты, что зовешь нас с Фивами на пир.",0,1246,0,0],["v","Да, горе нам: тебе, Агава, горе,",0,1247,0,0],["v","А за тобой и мне. Он, этот бог,",0,1248,0,0],["v","Был справедлив, конечно, но, жестокий,",0,1249,0,0],["v","Не пощадил и рода своего.",0,1250,0,1],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","не вслушиваясь еще в его слова, но уже несколько озадаченная его тоном"],["v","Ах, любит поворчать людская старость,",0,1250,0,0],["v","И ей не угодишь. (Помолчав.) А мой <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>?",0,1251,0,0],["v","Вот если бы он в мать пошел удачей,",0,1252,0,0],["v","Когда за зверем гонится в толпе",0,1253,0,0],["v","Товарищей. Да где ему! Он с богом",0,1254,0,0],["v","Бороться только может. Хоть бы ты",0,1255,0,0],["v","Его, отец, на ум наставил. Где ж он?",0,1255,0,0],["sd","(Ищет глазами вокруг.)"],["v","Пусть к матери счастливой подойдет",0,1256,0,0],["v","И на ее добычу хоть посмотрит.",0,1257,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","О горе, горе! Если только все,",0,1258,0,0],["v","Что сделали, поймете вы, ужасна",0,1259,0,0],["v","Скорбь ваша будет. Если ж навсегда",0,1260,0,1],["v","Пребудете в безумии, ни счастья,",0,1261,0,0],["v","Ни горя знать вам больше не дано.",0,1262,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","начинает прислушиваться к словам отца, разобрала слово «горе»"],["v","Да что же тут дурного, где тут <em>горе?</em>",0,1263,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["dir","приближаясь к <span class=\"ch\" data-ch=\"agava\">Агаве</span>"],["v","Ты к небу подними сперва глаза.",0,1264,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","смотрит на небо"],["v","Ну, подняла. Что там смотреть прикажешь?",0,1265,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Оно все то же? Перемены нет?",0,1266,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","опять смотрит на небо, потом на <span class=\"ch\" data-ch=\"kadm\">Кадма</span> — в некотором раздумье"],["v","Нет, будто стало ярче и лучистей.",0,1267,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Так не покинуло безумие тебя!",0,1268,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","понижая голос"],["v","Не знаю, что ты говоришь, но будто",0,1269,0,0],["v","В себя я прихожу теперь, отец.",0,1270,0,1],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Ты, выслушав меня, могла б ответить ясно?",0,1271,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","упавшим голосом, просто"],["v","Да, только прежнее забыла я, отец.",0,1272,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","В чей дом вошла ты с песней Гименея?",0,1273,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","За Эхиона отдал ты меня.",0,1274,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","А сын какой у твоего был мужа?",0,1275,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Пенфей, от брака нашего рожден.",0,1276,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","А чье лицо в руках твоих, Агава?",0,1277,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","с сомнением и некоторой тревогой в голосе"],["v","Чье? это — лев… Так мне сказали там.",0,1278,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["dir","внушительно"],["v","Вглядись в него, труд не велик, <span class=\"ch\" data-ch=\"agava\">Агава</span>.",0,1279,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Ай, (в ужасе) что я вижу? что я принесла?",0,1280,0,1],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["dir","настойчиво"],["v","Гляди, гляди, пока совсем признаешь!",0,1281,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","закрывая глаза свободной рукой"],["v","Я вижу, вижу скорбь свою, отец.",0,1282,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Что ж, голова на львиную похожа?",0,1283,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Нет, голову <span class=\"ch\" data-ch=\"penfey\">Пенфея</span> я ношу.",0,1284,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Что, не признавши, обагрила кровью.",0,1285,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","в смятенье"],["v","Убил-то кто? Как он попал ко мне?",0,1286,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["dir","с горечью"],["v","О, злая истина, пришла ты поздно.",0,1287,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","прерывающимся голосом"],["v","Ах, сердце не на месте. Не томи.",0,1288,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["dir","раздельно"],["v","Так знай: его убийцы — ты и сестры.",0,1289,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","совсем упавшим голосом"],["v","Где ж он погиб? в чертогах или где?",0,1290,0,1],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Где Актеон собаками растерзан.",0,1291,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Да как же на гору, злосчастный, он попал?",0,1292,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Пошел глумиться над служеньем вашим.",0,1293,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","ввинчиваясь в отца вопросами"],["v","Да мы, отец, как мы ушли туда?",0,1294,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Взбесились вы. Был полон <span class=\"ch\" data-ch=\"dionis\">Вакха</span> город.",0,1295,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","окончательно приходя в себя"],["v","Я поняла: нас <span class=\"ch\" data-ch=\"dionis\">Дионис</span> сгубил.",0,1296,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Разгневанный, что вами не был признан.",0,1297,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","ужас сменяется скорбью"],["v","А тело сына, где оно, отец?",0,1298,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["dir","указывая на носилки"],["v","Вот — труп. Его насилу разыскал я.",0,1299,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","На месте все? Все сложено опять?..<a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,1300,0,1],["v","За мать безумную неужто ж сын в ответе?",0,1300,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Как вы, он бога не хотел признать, —",0,1301,0,0],["v","Тогда всех нас одной бедой покрыл он:",0,1302,0,0],["v","Вы, и <span class=\"ch\" data-ch=\"penfey\">Пенфей</span>, и весь наш род погиб.",0,1303,0,0],["v","И мне, которому не дали боги сына,",0,1304,0,0],["v","Теперь приходится смотреть на отпрыск твой,",0,1305,0,0],["v","Убитый так злодейски, так позорно.",0,1306,0,0],["sd","(Обращается к останкам <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>, к которым присоединил и окровавленную голову, взяв ее от <span class=\"ch\" data-ch=\"agava\">Агавы</span>.)"],["v","Дитя мое, с надеждой на тебя",0,1307,1,0],["v","Мой дом взирал, ты был его опорой!",0,1308,0,0],["v","Пенфей, тебя весь город трепетал.",0,1309,0,0],["v","И старика, как на тебя посмотрит,",0,1310,0,1],["v","Никто бы не подумал оскорбить.",0,1311,0,0],["v","Теперь же из дому, пожалуй, выгнан",0,1312,1,0],["v","С позором буду я, великий <span class=\"ch\" data-ch=\"kadm\">Кадм</span>,",0,1313,0,0],["v","Тот <span class=\"ch\" data-ch=\"kadm\">Кадм</span>, что здесь, посеяв род фиванцев,",0,1314,0,0],["v","Такую жатву дивную собрал.",0,1315,0,0],["v","О, муж любимейший! тебя уж нет со мною,",0,1316,0,0],["v","А все тебя по-прежнему люблю.",0,1317,0,0],["v","До бороды рукой уж не коснешься,",0,1318,0,0],["v","Уж не обнимешь деда, дорогой.",0,1319,0,0],["v","Не скажешь: \"Кто, старик, тебя обидел?",0,1320,0,1],["v","Кто сердце растревожил и смутил?",0,1320,0,0],["v","Скажи, отец, и дерзкий мне ответит\".",0,1321,0,0],["v","Теперь несчастлив я,",0,1322,0,0],["sd","(Кивая головой на <span class=\"ch\" data-ch=\"agava\">Агаву</span>)"],["v","и ты горька,",0,1323,4,0],["v","Мать бедная, весь род с тобою страждет.",0,1323,0,0],["sd","(Воздевая руки.)"],["v","О смертный! Если небо ты презрел,",0,1324,0,0],["v","Взглянув на эту смерть, в богов уверуй!",0,1325,0,0],["sp","Хор"],["v","Старик! тебя мне жаль: хоть заслужил",0,1326,0,0],["v","<span class=\"ch\" data-ch=\"penfey\">Пенфей</span> свой жребий, все же горько деду.",0,1326,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Смотри, отец, как изменилась я",0,1327,0,0],["v",". . . . . . . . . . . . . . . .",0,1328,0,0],["sd","[Затем следовал «плач» <span class=\"ch\" data-ch=\"agava\">Агавы</span>. Вероятно, это было одно из сильнейших мест трагедии. <span class=\"ch\" data-ch=\"agava\">Агава</span> стремится обнять останки и не смеет коснуться до них оскверненными руками, наконец она побеждает свои религиозный страх и с плачем, с причитаниями покрывает поцелуями отдельные куски Пенфеева тела. В развязке пьесы на альтане, который возвышается у задней стены, замыкающей сцену, появляется <span class=\"ch\" data-ch=\"dionis\">Дионис</span>, уже как небожитель. Начало его речи, где он, объяснив вину <span class=\"ch\" data-ch=\"penfey\">Пенфея</span> и его наказание, определял сперва общую кару, потом особую <span class=\"ch\" data-ch=\"agava\">Агаве</span> с сестрами, потеряно вместе с плачем <span class=\"ch\" data-ch=\"agava\">Агавы</span>. Конец речи обращен к <span class=\"ch\" data-ch=\"kadm\">Кадму</span>.]"],["scene","Явление пятнадцатое","s19",7,19],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v",". . . . . . . . . . . . . . . . .<a class=\"nr\" href=\"#n-k40\" data-n=\"k40\" aria-label=\"Примечание 40\">40</a>",0,1329,0,0],["v","Драконом станешь ты, а дочь Арея,",0,1330,0,1],["v","Гармония, что в жены получил",0,1330,0,0],["v","Ты, смертный, тоже примет вид змеиный.",0,1331,0,0],["v","И повезут тебя с женой быки",0,1332,0,0],["v","Перед несчетной варварской дружиной,",0,1333,0,0],["v","И много городов ты разоришь:",0,1334,0,0],["v","<em>Оракул Зевса вам вещает это</em>.",0,1335,0,0],["v","Но Феба прорицалище твои",0,1335,0,0],["v","Разграбят воины и на возвратном",0,1336,0,0],["v","Пути постраждут. А тебя Арей",0,1337,0,0],["v","С Гармонией спасет и вас с женою",0,1338,0,0],["v","На острове блаженных поселит.<a class=\"nr\" href=\"#n-k41\" data-n=\"k41\" aria-label=\"Примечание 41\">41</a>",0,1339,0,0],["v","<em>Я</em> говорю вам это, сын Зевеса,",0,1340,0,1],["v","Не смертным порожденный <em><span class=\"ch\" data-ch=\"dionis\">Дионис</span></em>.",0,1340,0,0],["v","Вот если б скромно вы тогда почтили",0,1341,0,0],["v","Во мне рожденье Зевса, я б теперь",0,1342,0,0],["v","Вам счастье дал, как верный ваш союзник.",0,1343,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Мы виноваты, сжалься, Дионис!",0,1344,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Нет, к богу вы идете слишком поздно.",0,1345,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Ты прав, о бог, но чересчур суров…",0,1346,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Я, бог, терпел от смертных поношенье.",0,1347,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Но разве смертный гнев пристал богам?",0,1348,0,0],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Отец мой Зевс все порешил давно.",0,1349,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Все кончено, старик! О, мрак изгнанья!",0,1350,0,1],["sp","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>"],["v","Что медлить! Рок свершится — все равно.",0,1350,0,0],["scene","Явление шестнадцатое","s20",7,20],["sd","<span class=\"ch\" data-ch=\"dionis\">Дионис</span> исчезает. Следует сцена прощанья <span class=\"ch\" data-ch=\"agava\">Агавы</span> с отцом."],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Дитя мое, беда приспела злая",0,1351,0,0],["v","На нас — и на тебя, и на сестер.",0,1352,0,0],["v","И мне приходится на старости печальной",0,1353,0,0],["v","Переселяться к варварам. Увы,",0,1354,0,0],["v","Оракул мне сказал, что на Элладу",0,1355,0,0],["v","Я варварское войско приведу:",0,1356,0,0],["v","Дракон с змеею, <span class=\"ch\" data-ch=\"kadm\">Кадм</span> и дочь Арея,",0,1357,0,0],["v","Мы во главе их смешанных дружин",0,1358,0,0],["v","Пойдем на алтари, гробницы греков…",0,1359,0,0],["v","И Ахеронта волны не дадут",0,1360,0,1],["v","Злосчастному от бед успокоенья.",0,1361,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Отец, как ты уйдешь, меня ушлют…",0,1362,0,0],["sd","(Обнимает <span class=\"ch\" data-ch=\"kadm\">Кадма</span> и прижимается к нему с нежной мольбою.)"],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Дитя, зачем бессильного с мольбою",0,1363,0,0],["v","Ты лебедя седого обняла?",0,1364,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Кто даст приют отверженной, несчастной?",0,1365,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Не знаю, дитятко. Отцу не защитить.",0,1366,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Прощай, чертог! Прощай, отцовский город!",0,1367,0,0],["v","Для горя покидаю я тебя",0,1370,0,1],["v","Изгнанницей, мой терем.",0,1370,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Туда пойди теперь, где Аристеев…<a class=\"nr\" href=\"#n-k42\" data-n=\"k42\" aria-label=\"Примечание 42\">42</a>",0,1371,0,0],["v",". . . . . . . . . . . . . . . . . .",0,1372,0,0],["sd","[Дальнейшие строки потеряны. <span class=\"ch\" data-ch=\"kadm\">Кадм</span> посылает дочь на Киферон, на то место, где погиб сын Аристея — Актеон и где только что она сама убила <span class=\"ch\" data-ch=\"penfey\">Пенфея</span>: ей надо оттуда привести сестер, своих будущих спутниц в изгнании.]"],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Отец, я плачу над тобой!",0,1373,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","И я тебя оплакал… всех вас, дети.",0,1374,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","В дом твой горе принес",0,1375,0,0],["v","<span class=\"ch\" data-ch=\"dionis\">Дионис</span>-властелин,",0,1375,0,0],["v","Горе злое.",0,1376,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Горько было и <span class=\"ch\" data-ch=\"dionis\">Вакху</span>, как в Фивах",0,1377,0,0],["v","Вы почтить не хотели его.",0,1378,0,0],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["v","Ты прости, мой отец!",0,1379,0,0],["sp","<span class=\"ch\" data-ch=\"kadm\">Кадм</span>"],["v","Будь здорова,",1,1379,0,0],["v","Если можешь… несчастная дочь!",0,1380,0,1],["sp","<span class=\"ch\" data-ch=\"agava\">Агава</span>"],["dir","к спутницам"],["v","К сестрам меня ведите,",0,1380,0,0],["v","Их я возьму с собой",0,1381,0,0],["v","Горечь делить изгнанья…",0,1382,0,0],["v","Ты ж, ненавистный",0,1383,0,0],["v","Склон Киферона,",0,1384,0,0],["v","Век не видеть тебя!",0,1385,0,0],["v","Пусть для других менад",0,1386,0,0],["v","Тирсы красуются!",0,1387,0,0],["sd","(Уходит со спутницами.)"],["sp","Хор"],["v","Воли небесной различны явленья, —",0,1388,0,0],["v","Смертный не может ее угадать:",0,1389,0,0],["v","Много надежд проходит бесследно,",0,1390,0,1],["v","Многое боги нежданно дают…",0,1391,0,0],["v","Драме же нашей тут окончанье.",0,1392,0,0],["sd","По окончании драмы и уходе актеров со сцены, хор оставляет помост, двигаясь в том же порядке и тем же левым проходом. Хоревты уходят под звуки флейты."],["h1","Комментарий","comm"],["p","Трагедия написана в Македонии и поставлена в Афинах уже после смерти поэта вместе с «Ифигенией в Авлиде» и «Алкмеоном в Коринфе» (не сохранился). Трилогия была удостоена первого места."],["p","Сюжет «Вакханок» принадлежит к кругу мифов, связанных с установлением в Греции культа Диониса. Как бог — покровитель земледельцев и виноградарей, Дионис далеко не сразу получил признание в религии родовой знати; в состав гомеровских богов-олимпийцев он еще не входит, хотя «Илиада» знает уже о наказании, постигшем фракийского царя Ликурга за преследование Диониса (VI, 129 — 140). Не случайно, когда в VI в. до н. э. тираны, пришедшие к власти в различных городах Греции, старались идеологически ослабить знать, они вводили вместо старинных аристократических культов празднества в честь Диониса; в рамках этого культа, нашедшего сильную поддержку у афинского правителя Писистрата, как известно, возникла и достигла расцвета аттическая трагедия. Однако само сказание об утверждении Диониса в борьбе с врагами его религии обрабатывалось в произведениях афинских трагиков сравнительно редко: из примерно шестисот названий несохранившихся трагедий V — начала IV в. едва ли двадцать указывают на связь их содержания с мифами о Дионисе. Среди них — две трилогии Эсхила: первая — «Ликургия», изображавшая столкновение Диониса и его вакхической свиты с уже упоминавшимся фракийским царем; вторую составляли, по всей видимости, трагедии «Семела» (чудесное рождение Диониса), «Чесальщицы» (месть Диониса трем дочерям орхоменца Миния, не желавшим признать его власть) и «Пенфей» — последняя, по словам античного комментатора, являлась предшественницей еврипидовских «Вакханок». Так как от обеих трилогий Эсхила сохранились только незначительные отрывки, «Вакханки» являются для нас единственным литературным памятником классического периода древнегреческой литературы, запечатлевшим миф о борьбе Диониса с его противниками."],["p","«Вакханки» — первая трагедия Еврипида, переведенная Анненским (отдельное издание, СПб., 1894). В ней еще не устоялись его обычные приемы нумерации «явлений», подачи ремарок и т. п.: так, в ремарки вводятся объяснения, что такое парод, как выглядели декорации и проч. (вторая фраза вступительной ремарки: «На задней стене, замыкающей сцену (проскений), намалевана декорация фасада дворца в дорийском стиле, с колоннами и триглифом)». В этих местах мы делали унифицирующие сокращения, а ремарки комментирующего характера (к песням хора) переносили в нижеследующие примечания. Готовя итоговое издание «Театра Еврипида», Анненский собирался переработать свой перевод; ссылаясь на это его намерение, Ф. Ф. Зелинский в посмертном издании переписал его работу почти на треть. Главным образом это коснулось апологии Диониса (ст. 266 — 327) и развязки, где Зелинский сделал существенные перестановки в соответствии со своей собственной реконструкцией греческого текста. Эту реконструкцию он мотивировал еще в 1894 — 1895 гг., сопроводив ее своим собственным прозаическим переводом «Вакханок» по реконструированному тексту («Филологическое обозрение», т. 6 — 7). Перевод Зелинского, представляющий самостоятельный интерес и любопытный для сопоставления с переводом Анненского, мы приводим в разделе «Дополнения», а перевод Анненского, при всем несовершенстве его первого опыта, даем в его настоящем виде, освобожденном от редактуры Зелинского. Это делается впервые: в переизданиях 1968 и 1980 гг. «Вакханки» (в порядке исключения) перепечатывались с правкой Зелинского."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"],["note","k40"],["note","k41"],["note","k42"]],"n":{"k1":["Ст. 13 — 22","В описании пути Диониса в Грецию с Ближнего Востока сохраняется воспоминание о близких связях, существующих между этим богом и его финикийским двойником Адонисом, а также шумеро-вавилонским Думузи-Таммузом."],"k2":["Ст. 23. Небрида","шкура молодого оленя."],"k3":["Ст. 25. …сестры матери…","У Кадма, по мифологической генеалогии, было четыре дочери: Семела, Автоноя (мать Актеона), Инб и Агава, мать Пенфея (см. ст. 229 — 231)."],"k4":["Ст. 55. Тмол","гора в Лидии."],"k5":["Ст. 65","Ремарка Анненского: «Вступительная песнь хора (под аккомпанемент флейтиста) раскрывает перед нами полную картину культа Диониса. Она полна веселого и невозбранного одушевления и вся проникнута живым общением с природой…»"],"k6":["Ст. 120 — 131","Когда Рея родила Зевса, она спрятала его в Диктейской пещере на Крите и велела местным божествам — куретам бить в тимпан («обруч, кожей одетый»), чтобы заглушить крики младенца: его отец Кронос, боясь своего свержения с престола богов, проглатывал живыми своих только что рожденных детей. Затем тимпан нашли корибанты, служители Великой Матери богов — малоазийской богини, сближаемой то с Деметрой (см. примеч. к «Елене», ст. 1301 — 1368), то с Реей, от которых он перешел к вакханкам. Все эти детали являются, по-видимому, измышлением самого Еврипида. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Елена», Ст. 1301 — 1368.</b> — «дифирамбический стасим» такого же типа, как в «Ифигении в Тавриде» (см. примеч. к ст. 1234 — 1283). Содержание его составляет, как и там, «священное повествование» — на этот раз о похищении Аидом Персефоны, дочери богини земледелия и плодородия Деметры. Последняя при этом отождествляется с фригийской Великой Матерью — богиней Кибелой (Мать блаженных, гор царица, мчащаяся в колеснице с львиной запряжкой), экстатический культ которой сближался с шумным, оргиастическим ритуалом Диониса. Смысл ст. 1353 — 1357 остается не вполне ясным: с какой стати спартанка Елена должна была посещать празднества фригийской Матери или даже афинские таинства в честь Деметры? Некоторые ученые видят здесь намек на положение дел в современных Еврипиду Афинах, где неудачи в ходе Пелопоннесской войны вызвали падение религиозного благочестия.</span><!--/xn-->"],"k7":["Ст. 133. Через два года на третий…","справляемые раз в три года празднества в честь Диониса."],"k8":["Ст. 135. Пакты","золотоносная река в Лидии, берущая начало на г. Тмоле."],"k9":["Ст. 200 — 203","И где те речи, что низвергнут их… — В уста Тиресия вложена полемика с идеями софиста Протагора, изложенными в его сочинении «Низвергающие речи»."],"k10":["Ст. 233. …с мужчиной ложе разделить!","Дионисийским оргиям, носившим с самого их зарождения характер аграрной магии, первоначально был, несомненно, присущ элемент полового разгула, который рассматривался как средство стимулировать плодородие природы. В «Вакханках», однако, это подозрение Пенфея (ср. ст. 354, 454, 487, 957 сл.) не находит подтверждения (см. ст. 686 — 688, 693 сл.)."],"k11":["Ст. 266 — 271","Критика ораторского искусства, используемого в корыстных целях безответственными политическими лидерами."],"k12":["Ст. 284 — 286. …сам бог, богам он отдается на возлиянье…","Идея, использованная впоследствии христианскими писателями для обоснования обряда причащения к «крови господней»."],"k13":["Ст. 286 — 297","Рационалистическое толкование мифа, основанное в подлиннике на игре слов homeros — «заложник» и ho meros — «бедро»."],"k14":["Ст. 305. Гора двуглавая","Парнас."],"k15":["Ст. 337 — 340","Древний вариант мифа об Актеоне, ставящий его в один ряд с другими преданиями о гневе богов, раздраженных похвальбой смертного. Более распространенная версия — Актеон увидел обнаженной купающуюся Артемиду — эллинистического происхождения."],"k16":["Ст. 367. …Пенфей-горюн…","Здесь, как и в ст. 508, Еврипид сближает имя Пенфея (Pentheus) со словом penthos — «горе», «скорбь»."],"k17":["Ст. 370","Ремарка Анненского: «Хор поет свою вторую песню…» В песне слышится уже некоторый душевный разлад, тревога. Правда, призывается посмотреть на дела Пенфея. Как скромны, просты, общедоступны требования Вакха и как неразумны те, которые его отвергают! Вакх — бог мира и счастия. Излюбленная страна вакханок — это Македония, где их уважают."],"k18":["Ст. 409. Обитель муз…","Пиерия, на склонах Олимпа; здесь, в Македонии, писал Еврипид своих «Вакханок». В параллель Македонии, северному краю греческого мира, названы Египет (в подлиннике — Фарос, Остров в устье Нала), южный его край, и Кипр, восточный его край."],"k19":["Ст. 419. Мир","греч. Eirene (см. примеч. к «Оресту», ст. 1684). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Орест», Ст. 1684. …почтите теперь Тишину….</b> В оригинале богиня названа Eirene, что соответствует русскому понятию «мир». После поражения спартанцев при Кизике (весной 410 г.) с их стороны дважды делались мирные предложения, которые отвергались сторонниками продолжения войны во главе с Клеофонтом (см. примеч. к ст. 902 — 906). Еврипид, как видно из этих стихов, не разделял подобных воинственных настроений.</span><!--/xn-->"],"k20":["Ст. 486. Мрак имеет обаянье","неточный перевод, проистекающий из стремления всячески подчеркнуть подавляемую Пенфеем в себе чувственность. В оригинале сказано: «В мраке есть священная торжественность»."],"k21":["Ст. 499. В толпу вакханок прежде попади.","«Т. е. это настолько же невозможно, как теперь тебе попасть на волю и уйти на Киферон» (примеч. И. Анненского)."],"k22":["Ст. 519 — 522","Ремарка Анненского: «Тревога, почти отчаяние, охватывает хор. Он взывает к Фивам, олицетворяя их в Диркее, одной их фиванских рек, и ищет защиты у родины Диониса. Вслед за обращением к Фивам идет обращение к Дионису, которого вакханки зовут на помощь. Мечта между тем рисует им отрадные картины вольных странствий Диониса с дружиной. По ходу пьесы хору надо идти в рабство к Пенфею. Но угроза царя остается неисполненной, потому что мысли Пенфея заняты пленником: притом же хор, по сценическим традициям, не мог бы покинуть орхестры». Диркея — источник вблизи Фив; поскольку матерью Диониса была фиванка Семела, то естественно, что он был омыт водами Диркеи. Ахелой — бог одноименной реки, протекающей по границе Акарнании с Этолией (западная часть Средней Греции), считался отцом всех греческих рек."],"k23":["Ст. 525. Дифирамб\".","Это слово (вероятно, малоазийского происхождения) Еврипид употребляет здесь как имя собственное нового бога, культовой песнью которого действительно являлся дифирамб."],"k24":["Ст. 539 — 541. …Земли исчадье… семя Эхиона…","То есть потомок «спартов» (см. вступит, заметку к «Финикиянкам»). Имя Эхион ассоциируется со словом echis — «змея»."],"k25":["Ст. 556. Ниса","название нескольких городов и поселений (в Индии, Лидии, Карий, Эфиопии, Фракии и др.); которое из них здесь имеется в виду, трудно сказать с уверенностью."],"k26":["Ст. 560 — 564. Поущелиям Олимпа, где игру Орфея слушать…","Местопребыванием Орфея в мифологии обычно считалась гора Пангей во Фракии; Еврипид называет Олимп, вероятно, из благодарности к своему гостеприимному хозяину Архелаю."],"k27":["Ст. 570 — 575","Аксий (ныне Вардар) и Лидий — реки в Македонии; Лидий вытекает из озера, на котором стояла царская столица Пелла. Еврипид обыгрывает созвучие его названия с названием малоазийской Лидии, откуда пришел Дионис."],"k28":["Ст. 604","Ремарка Анненского: «Рассказ Диониса ведется не обычным ямбическим размером, а трохеями: в этом ритме чувствуется больше движения. Хотя тон речи бога спокоен, но живой размер более соответствует возбужденному характеру самого действия и настроению зрителей, в которых не улеглось еще волнение от угрозы Диониса». Однако 8-стопный хорей подлинника («трохаический тетраметр»), видимо, показался Анненскому слишком быстрым для русского уха, и он заменил его более спокойным 5-стопным хореем."],"k29":["Ст. 652","В рукописях стих пропущен и восполняется переводчиками по догадке."],"k30":["Ст. 749 — 751. Асоп","река на юге Беотии; Эрифры — город там же, недалеко от Платен; Гисии — поселение на склоне Киферона."],"k31":["Ст. 756","…И на землю не падали малютки. ~ После этого стиха, по мнению некоторых издателей, в рукописях выпали один-два стиха, которые Зелинский восстанавливает по догадке:<br>Все, что хотели, на руки они<br>Могли поднять: ни меди, ни железа<br>Им тяжесть не противилась; на кудрях<br>У них огонь горел — и их не жег."],"k32":["Ст. 781. К Электриным воротам.","См. «Финикиянки», ст. 1129, 1570."],"k33":["Ст. 787","Ремарка Анненского: «В этой сцене начинается катастрофа: настроение и образ мыслей Пенфея меняется, ст. 810»."],"k34":["Ст. 821. Виссоновые ткани","одежды из очень тонкого полотна."],"k35":["Ст. 862","Ремарка Анненского: «В хоре слышится бодрое настроение. Мечты о вакханалии становятся рельефнее. Заманчивая картина полного избавления и свободы неразрывна с представлением о мести и торжестве над приниженным врагом. Чувствуется уверенность в непреложности небесной кары. Счастье — не в надеждах и мечтах, а в обладании счастливым мгновением»."],"k36":["Ст. 976","Ремарка Анненского: «Хор воспевает месть менад и призывает кару на голову Пенфея. В антистрофе слышится мораль, спокойный голос рассудка, но голос мстительной страсти заглушает его. В эподе — обращение к богу: пусть он по-своему »весело« покарает лазутчика менад». Лима — олицетворение безумия (см. «Геракл», ст. 834 сл.)."],"k37":["Ст. 990. Ливийские горгоны.","Обычно мифологическая традиция локализовала горгон на Крайнем Западе."],"k38":["Ст. 1036","Реплика вестника в рукописи не окончена; Ф. Зелинский дополняет ее по смыслу:<br>Ты думаешь, так оскудели Фивы,<br>Что наказать не сможет вас никто?"],"k39":["Ст. 1300","После этого стиха в рукописи утрачено несколько стихов."],"k40":["Ст. 1329","После этого стиха в сохранившихся рукописях следует сразу монолог Диониса, начинающийся к тому же с середины. Поэтому исследователи текста Еврипида давно сошлись во мнении, что те — всего лишь две — рукописи XIV в., в которых содержатся «Вакханки», списаны с дефектного экземпляра, и между стихами 1329 и 1330 должно было находиться завершение диалога Агавы и Кадма, плач Агавы и та часть монолога Диониса, в которой он излагал дальнейшую судьбу Агавы и ее сестер. Эта утерянная часть трагедии только отчасти восстанавливается из византийской церковной драмы XI века «Страждущий Христос»: для изображения «Страстей Господних» и плача Девы Марии над телом сына византийский автор склеивал по строчке отрывки из «языческих» трагедий древних греков. Из «Вакханок» он включил в свои труд целиком или в отрывках с небольшими переделками свыше двухсот стихов. Для плача Агавы из «Страждущего Христа» извлекаются следующие стихи (в переводе Ф. Ф. Зелинского): 1311 — 1313. Тебя я мертвого в руках держу! О, как могла бы бережно, мой милый, К груди своей тебя прижать, оплакать… 1256 сл. Как приласкать растерзанные члены, Облобызать мной вскормленную плоть? 1466 — 1472. Дай, старче, голову несчастной жертвы Приладим к телу и, насколько можем, Его останки воссоединим. О, милый лик, ланиты молодые… Нет, нет, покровом осеним главу! О, образ окровавленный, о, члены Изборожденные… Каким мне саваном тебя покрыть? Чьи руки верные тебя омоют? Из речи Диониса автором византийской драмы заимствованы, по-видимому, следующие стихи. Об участи Пенфея: 1664. Дерзнул в оковы бога заковать И поносить кощунственною речью. 1663. За это смерть он претерпел от тех, Кому он был дороже всех на свете. 1667. И жертвой пал он справедливой кары. Затем об участи Агавы и ее сестер: 1674. В возмездие за пролитую кровь Оставьте город этот: благочестье 1676. Не дозволяет жить убийце рядом С могилою убитого. Наконец, об участи Кадма: 1690. Твою ж судьбу поведаю тебе… — после чего вскоре следовал ст. 1330 сл. нашей трагедии."],"k41":["Ст. 1330 — 1339","Согласно одной из версий мифа, Кадм с Гармонией покинули Фивы при загадочных обстоятельствах еще при жизни Пенфея и переселились в Иллирию, где Кадм возглавил борьбу местного племени энхелейцев против иллирийцев, одержал победу и некоторое время царствовал над энхелейцами. Потом уже он и супруга были превращены в змей. По другому варианту мифа, Кадм, как зять бога Ареса, после смерти был перенесен на острова блаженных. Здесь эти две версии соединены не слишком умело, но состояние текста лишает исследователей возможности установить причину или источник подобной комбинации. К основному конфликту «Вакханок» дальнейшая судьба Кадма имеет вообще отдаленное отношение."],"k42":["Ст. 1371","После этого стиха опять пропуск; переводчик восстанавливает его, исходя из сохранившихся слов «Аристеева сына», т. е. Актеона, погибшего там же, где был растерзан Пенфей (см. ст. 1291)."]},"mainEnd":2026,"c":[{"id":"dionis","name":"Дионис","role":"Бог, сын Зевса и Семелы","intro":"Бог, пришедший в Фивы в облике юного чужеземца, чтобы утвердить свой культ.","arc":"Дионис — главное действующее лицо и режиссёр трагедии. Сёстры его матери отрицают его божественность, Пенфей запрещает вакхические обряды, и бог решает показать Фивам свою силу. Он мягок и насмешлив в облике пленника, но его кара беспощадна: Пенфей, переодетый вакханкой, гибнет от рук собственной матери. В финале Дионис является в истинном облике и объявляет приговор всему роду Кадма.","st":[{"i":206,"p":10,"l":"Пролог · явление первое","t":"Пролог","d":"Объявляет, что пришёл в Фивы в человеческом облике, чтобы покарать сестёр Семелы и Пенфея и учредить свой культ.","c":"","k":true},{"i":727,"p":36,"l":"Действие второе · явление четвертое","t":"Пленный чужеземец","d":"Связанным приведён к Пенфею; спокойно отвечает на допрос о таинствах, предупреждает, что бог освободит его.","c":"","k":false},{"i":898,"p":44,"l":"Действие третье · явление шестое","t":"Чудо во дворце","d":"Сотрясает дворец, разрушает тюрьму и выходит к вакханкам свободным.","c":"Бог показывает силу.","k":false},{"i":1218,"p":60,"l":"Действие третье · явление девятое","t":"Искушение","d":"Предлагает Пенфею тайно посмотреть на вакханок, переодевшись женщиной.","c":"Начало расправы.","k":true},{"i":1390,"p":69,"l":"Действие четвертое · явление десятое","t":"Пенфей в женском платье","d":"Поправляет ему складки и локоны и ведёт на Киферон.","c":"","k":false},{"i":1959,"p":97,"l":"Исход · явление пятнадцатое","t":"Явление бога","d":"В истинном облике объявляет приговор: Кадм и Гармония станут змеями, Агава уйдёт в изгнание.","c":"","k":false}],"gen":"Дионис"},{"id":"penfey","name":"Пенфей","role":"Юный царь Фив, внук Кадма","intro":"Царь, запретивший культ нового бога в Фивах.","arc":"Пенфей — рационалист и блюститель порядка, который видит в вакхических обрядах только разврат. Но за его гневом скрывается тайное любопытство, и Дионис играет на нём: царь соглашается переодеться в женское платье, чтобы подглядеть за вакханками. Его гибель — растерзание руками матери и тёток.","st":[{"i":490,"p":24,"l":"Действие первое · явление третье","t":"Гнев царя","d":"Вернувшись в Фивы, грозит схватить вакханок и чужеземца; насмехается над Кадмом и Тиресием.","c":"","k":false},{"i":727,"p":36,"l":"Действие второе · явление четвертое","t":"Допрос","d":"Допрашивает пленного чужеземца, велит остричь ему локоны и запереть в конюшне.","c":"","k":true},{"i":1079,"p":53,"l":"Действие третье · явление восьмое","t":"Рассказ пастуха","d":"Узнаёт о чудесах вакханок на Кифероне и решает идти на них войной.","c":"","k":false},{"i":1218,"p":60,"l":"Действие третье · явление девятое","t":"Согласие","d":"Поддаётся искушению подсмотреть за вакханками.","c":"Роковое решение.","k":true},{"i":1390,"p":69,"l":"Действие четвертое · явление десятое","t":"В женском платье","d":"В одеждах вакханки, полубезумный, видит двух солнц и быка вместо чужеземца.","c":"","k":false},{"i":1594,"p":79,"l":"Действие пятое · явление одиннадцатое","t":"Растерзан","d":"Вестник рассказывает: Агава и вакханки растерзали его, приняв за льва.","c":"","k":false}],"gen":"Пенфей"},{"id":"agava","name":"Агава","role":"Дочь Кадма, мать Пенфея","intro":"Мать, растерзавшая сына в вакхическом безумии.","arc":"Агава появляется только в последней части, но её сцена — вершина трагедии. С головой сына в руках она гордится «охотничьей добычей», и Кадм медленно возвращает её к сознанию. Узнавание оборачивается невыносимым горем.","st":[{"i":1594,"p":79,"l":"Действие пятое · явление одиннадцатое","t":"Убийство","d":"Вестник рассказывает: первой бросилась на сына и вырвала ему руку.","c":"","k":false},{"i":1722,"p":85,"l":"Исход · явление тринадцатое","t":"Добыча","d":"Входит с головой Пенфея на тирсе, ликуя и зовя отца разделить пир.","c":"","k":false},{"i":1923,"p":95,"l":"Исход · явление четырнадцатое","t":"Пробуждение","d":"Кадм заставляет её взглянуть на небо, затем на голову — и она узнаёт сына.","c":"Безумие сменяется ужасом.","k":true},{"i":2025,"p":100,"l":"Исход · явление шестнадцатое","t":"Изгнание","d":"Прощается с отцом и уходит из Фив.","c":"","k":false}],"gen":"Агава"},{"id":"kadm","name":"Кадм","role":"Основатель Фив, дед Пенфея","intro":"Старый царь, принявший культ внука — Диониса.","arc":"Кадм почитает Диониса из благоразумия и родственной выгоды. В конце он, как и весь род, наказан: ему суждено стать змеем.","st":[{"i":279,"p":14,"l":"Действие первое · явление второе","t":"Старики-вакханты","d":"С Тиресием, в венках и с тирсами, собирается плясать в честь бога.","c":"","k":false},{"i":1923,"p":95,"l":"Исход · явление четырнадцатое","t":"Возвращение Агавы к разуму","d":"Приносит останки Пенфея и открывает дочери правду.","c":"","k":true},{"i":2025,"p":100,"l":"Исход · явление шестнадцатое","t":"Приговор","d":"Узнаёт, что станет змеем, и прощается с дочерью.","c":"","k":false}],"gen":"Кадм"},{"id":"tiresiy","name":"Тиресий","role":"Слепой прорицатель","intro":"Мудрый старик, первым признавший Диониса.","arc":"Тиресий даёт богословское обоснование нового культа: Деметра дала людям хлеб, Дионис — вино.","st":[{"i":490,"p":24,"l":"Действие первое · явление третье","t":"Отповедь Пенфею","d":"Объясняет природу бога и предостерегает царя.","c":"","k":true}]}]};
